  function saveReelFeedCache() {
    try {
      /* Large social feeds do not persist an ever-growing copy of the session
         feed on the client. Keep a small metadata fallback pool; video bytes are
         cached independently by the browser's media/HTTP cache. */
      const serializable = reelFeed.slice(0, 24).map(function (reel) {
        const copy = Object.assign({}, reel);
        delete copy.cachedVideo;
        delete copy.handoffTime;
        if (/^blob:/i.test(String(copy.thumbnailUrl || '')) && copy.id) copy.thumbnailUrl = '/api/reels/' + encodeURIComponent(copy.id) + '/thumbnail';
        return copy;
      });
      localStorage.setItem(reelFeedCacheKey(), JSON.stringify(serializable));
    } catch (_error) {}
  }

  function restoreReelFeedCache() {
    try {
      const cached = JSON.parse(localStorage.getItem(reelFeedCacheKey()) || '[]');
      return Array.isArray(cached) ? cached : [];
    } catch (_error) {
      return [];
    }
  }

  async function restoreCachedReelVideo(reel) {
    return false;
  }

  async function cacheReelVideo(reel, sourceData) {
    /* Do not fetch/cache complete Reel files. Playback now relies on HTTP range
       requests plus proximity preloading, so bandwidth is spent only on media
       the user is likely to watch. */
    return false;
  }

  function reelPosterSourceKey(reel, video) {
    try {
      const source = String((video && (video.currentSrc || video.src)) || (reel && (reel.cachedVideo || reel.video)) || '');
      /* Object URLs are session-specific, so use the stable reel URL whenever
       * possible. This key prevents a captured frame from ever being reused by
       * a different Reel after DOM blocks/videos are recycled. */
      return String((reel && reel.video) || source);
    } catch (_error) {
      return String((reel && reel.video) || '');
    }
  }

  function captureReelPoster(reel, video) {
    return String((reel && reel.thumbnailUrl) || '');
  }

  const repairedReelPosterIds = new Set();
  async function repairReelPosterFromVideo(reel, video) {
    if (!reel || !reel.id || !video || video.readyState < 2 || !video.videoWidth || !video.videoHeight) return false;
    const id = String(reel.id);
    if (repairedReelPosterIds.has(id)) return false;
    repairedReelPosterIds.add(id);
    try {
      const maxEdge = 960;
      const scale = Math.min(1, maxEdge / Math.max(video.videoWidth, video.videoHeight));
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(2, Math.round(video.videoWidth * scale));
      canvas.height = Math.max(2, Math.round(video.videoHeight * scale));
      const context = canvas.getContext('2d', { alpha:false, desynchronized:true });
      if (!context) throw new Error('poster canvas unavailable');
      context.drawImage(video, 0, 0, video.videoWidth, video.videoHeight, 0, 0, canvas.width, canvas.height);
      const blob = await new Promise(function(resolve){ canvas.toBlob(function(value){ resolve(value && value.size ? value : null); }, 'image/jpeg', .84); });
      canvas.width = 1; canvas.height = 1;
      if (!blob) throw new Error('poster capture failed');
      const response = await fetch('/api/reels/' + encodeURIComponent(id) + '/thumbnail', {
        method:'PUT', credentials:'same-origin', headers:{'Content-Type':'image/jpeg'}, body:blob
      });
      if (!response.ok) throw new Error('poster upload failed');
      reel.thumbnailUrl = '/api/reels/' + encodeURIComponent(id) + '/thumbnail?v=' + Date.now();
      saveReelFeedCache();
      return true;
    } catch (_error) {
      repairedReelPosterIds.delete(id);
      return false;
    }
  }

  async function deleteCachedReelVideo(reel) {
    if (!reel) return;
    const key = String(reel.id || '');
    const objectUrl = reelVideoObjectUrls.get(key);
    if (objectUrl) URL.revokeObjectURL(objectUrl);
    reelVideoObjectUrls.delete(key);
    if (!window.caches || !reel.video) return;
    try {
      const cache = await caches.open(reelVideoCacheName);
      await cache.delete(new Request(new URL(reel.video, location.href).href, { credentials: 'same-origin' }));
    } catch (_error) {}
  }

  function profileDataCacheRequest(userId) {
    return new Request(new URL('/__facebook_profile_cache__/' + encodeURIComponent(cacheScope) + '/' + encodeURIComponent(String(userId || '')), location.origin).href);
  }

  async function cacheProfileView(user, posts) {
    if (!user || !user.id || !window.caches) return false;
    try {
      const cleanUser = Object.assign({}, user);
      delete cleanUser._cachedPosts;
      const cache = await caches.open(profileDataCacheName);
      await cache.put(profileDataCacheRequest(user.id), new Response(JSON.stringify({
        user: cleanUser,
        posts: Array.isArray(posts) ? posts : [],
        cachedAt: Date.now()
      }), { headers: { 'Content-Type': 'application/json' } }));
      return true;
    } catch (_error) {
      return false;
    }
  }

  async function readCachedProfileView(userId) {
    if (!userId || !window.caches) return null;
    try {
      const cache = await caches.open(profileDataCacheName);
      const response = await cache.match(profileDataCacheRequest(userId));
      if (!response) return null;
      const data = await response.json();
      if (!data || !data.user || String(data.user.id) !== String(userId)) return null;
      data.user._cachedPosts = Array.isArray(data.posts) ? data.posts : [];
      return data.user;
    } catch (_error) {
      return null;
    }
  }

  function postFeedCacheRequest() {
    return new Request(new URL('/__facebook_post_feed_cache__/' + encodeURIComponent(cacheScope) + '/' + encodeURIComponent(String(profile && profile.id || 'signed-in')), location.origin).href);
  }

  async function cachePostFeed(posts) {
    if (!window.caches || !profile) return false;
    try {
      const cache = await caches.open(postFeedCacheName);
      await cache.put(postFeedCacheRequest(), new Response(JSON.stringify({
        posts: Array.isArray(posts) ? posts : [],
        cachedAt: Date.now()
      }), { headers: { 'Content-Type': 'application/json' } }));
      return true;
    } catch (_error) {
      return false;
    }
  }

  async function readCachedPostFeed() {
    if (!window.caches || !profile) return [];
    try {
      const cache = await caches.open(postFeedCacheName);
      const response = await cache.match(postFeedCacheRequest());
      if (!response) return [];
      const data = await response.json();
      return data && Array.isArray(data.posts) ? data.posts : [];
    } catch (_error) {
      return [];
    }
  }

