  function readCachedProfile() {
    try {
      const cached = JSON.parse(localStorage.getItem(profileCacheKey) || 'null');
      if (!cached || typeof cached !== 'object') return null;
      if (String(cached.dataNamespace || '') !== dataNamespace) return null;
      cached.profilePhoto = localStorage.getItem('profilePhoto') || cached.profilePhoto || '';
      cached.coverPhoto = localStorage.getItem('coverPhoto') || cached.coverPhoto || '';
      cached.bio = cached.bio || localStorage.getItem('profileBio') || '';
      return cached;
    } catch (_error) {
      return null;
    }
  }

  function applyCachedProfileDetails(user) {
    const snapshot = user && user.profileDetails && typeof user.profileDetails === 'object' && !Array.isArray(user.profileDetails)
      ? user.profileDetails
      : {};
    const remote = snapshot.editorData && typeof snapshot.editorData === 'object'
      ? snapshot.editorData
      : (snapshot.mergedProfileData && typeof snapshot.mergedProfileData === 'object' ? snapshot.mergedProfileData : {});
    const remotePinned = Object.prototype.hasOwnProperty.call(snapshot, 'pinnedDetailsSelection')
      ? (Array.isArray(snapshot.pinnedDetailsSelection) ? snapshot.pinnedDetailsSelection : [])
      : [];
    try {
      const ownerId=String(user&&user.id||'');
      const storedOwner=String(localStorage.getItem('facebookProfileDetailsOwnerIdV1')||'');
      let editorData=Object.assign({},remote);
      let pinned=remotePinned;
      if(ownerId && storedOwner===ownerId){
        let local={};
        try{local=JSON.parse(localStorage.getItem('mergedProfileData')||'{}')||{};}catch(_error){}
        new Set(Object.keys(remote).concat(Object.keys(local))).forEach(function(key){
          const r=remote[key], l=local[key];
          if(r===undefined) editorData[key]=l;
          else if(l!==undefined && Number(l&&l.updatedAt||0)>Number(r&&r.updatedAt||0)) editorData[key]=l;
        });
        if(localStorage.getItem('pinnedDetailsSelection')!==null){
          try{const value=JSON.parse(localStorage.getItem('pinnedDetailsSelection'));if(Array.isArray(value))pinned=value;}catch(_error){}
        }
      }else if(ownerId){
        localStorage.removeItem('mergedProfileData');
        localStorage.removeItem('pinnedDetailsSelection');
        localStorage.removeItem('contactInformation');
        localStorage.removeItem('profileBio');
      }
      if(ownerId) localStorage.setItem('facebookProfileDetailsOwnerIdV1',ownerId);
      localStorage.setItem('mergedProfileData', JSON.stringify(editorData));
      localStorage.setItem('pinnedDetailsSelection', JSON.stringify(pinned));
      window.dispatchEvent(new CustomEvent('profiledetailsloaded', { detail: { editorData: Object.assign({}, editorData), pinnedDetailsSelection: pinned } }));
    } catch (_error) {}
  }

  function cacheProfile() {
    if (!profile) return;
    try {
      localStorage.setItem(profileCacheKey, JSON.stringify({
        id: profile.id,
        dataNamespace: dataNamespace,
        name: profile.name,
        bio: profile.bio || '',
        profileFrameName: profile.profileFrameName || '',
        profileFrameSvg: profile.profileFrameSvg || '',
        createdAt: profile.createdAt || '',
        profilePhotoUpdatedAt: profile.profilePhotoUpdatedAt || '',
        profileDetails: profile.profileDetails && typeof profile.profileDetails === 'object' ? profile.profileDetails : null
      }));
      putStoredPhoto('profilePhoto', profile.profilePhoto || '');
      putStoredPhoto('coverPhoto', profile.coverPhoto || '');
      localStorage.setItem('profileBio', profile.bio || '');
    } catch (_error) {}
  }

