  async function api(url, options) {
    const settings = Object.assign({ headers: { 'Content-Type': 'application/json' } }, options || {});
    if (!settings.method || String(settings.method).toUpperCase() === 'GET') settings.cache = 'no-store';
    const response = await fetch(url, settings);
    const data = await response.json().catch(function () { return {}; });
    if (!response.ok) throw new Error(data.error || 'Something went wrong.');
    return data;
  }

  function postUploadProgressElements() {
    return {
      root: document.querySelector('#fbHomePostUploadProgress'),
      label: document.querySelector('#fbHomePostUploadProgressLabel'),
      value: document.querySelector('#fbHomePostUploadProgressValue'),
      fill: document.querySelector('#fbHomePostUploadProgressFill')
    };
  }

  function showPostUploadProgress(percent, label) {
    const elements = postUploadProgressElements();
    const value = Math.max(0, Math.min(100, Math.round(Number(percent) || 0)));
    if (elements.root) elements.root.hidden = false;
    if (elements.label) elements.label.textContent = label || (value >= 100 ? 'Publishing…' : 'Posting…');
    if (elements.value) elements.value.textContent = value + '%';
    if (elements.fill) elements.fill.style.width = value + '%';
  }

  function resetPostUploadProgress() {
    const elements = postUploadProgressElements();
    if (elements.root) elements.root.hidden = true;
    if (elements.label) elements.label.textContent = 'Posting…';
    if (elements.value) elements.value.textContent = '0%';
    if (elements.fill) elements.fill.style.width = '0%';
  }

  function apiWithUploadProgress(url, options, onProgress) {
    const settings = options || {};
    return new Promise(function (resolve, reject) {
      const request = new XMLHttpRequest();
      request.open(String(settings.method || 'POST').toUpperCase(), url, true);
      request.withCredentials = true;
      const headers = Object.assign({ 'Content-Type': 'application/json' }, settings.headers || {});
      Object.keys(headers).forEach(function (name) { request.setRequestHeader(name, headers[name]); });
      request.upload.addEventListener('progress', function (event) {
        if (!event.lengthComputable || typeof onProgress !== 'function') return;
        onProgress(Math.min(99, Math.round(event.loaded / Math.max(1, event.total) * 100)), 'Uploading media…');
      });
      request.upload.addEventListener('load', function () {
        if (typeof onProgress === 'function') onProgress(100, 'Processing post…');
      });
      request.addEventListener('load', function () {
        let data = {};
        try { data = JSON.parse(request.responseText || '{}'); } catch (_error) {}
        if (request.status >= 200 && request.status < 300) resolve(data);
        else reject(new Error(data.error || 'Something went wrong.'));
      });
      request.addEventListener('error', function () { reject(new Error('Could not upload the post. Check your connection and try again.')); });
      request.addEventListener('abort', function () { reject(new Error('Post upload was cancelled.')); });
      request.send(settings.body == null ? null : settings.body);
    });
  }

  function message(text) {
    const toast = document.querySelector('#fbHomeToast');
    if (toast) {
      toast.textContent = text;
      toast.classList.add('is-visible');
      clearTimeout(message.timer);
      message.timer = setTimeout(function () { toast.classList.remove('is-visible'); }, 2200);
    } else {
      window.alert(text);
    }
  }

  function applyName() {
    if (!profile) return;
    document.querySelectorAll('.fb-dialog-user strong').forEach(function (element) {
      if (element.textContent !== profile.name) element.textContent = profile.name;
    });
    if (document.body.classList.contains('viewing-other-profile')) return;
    document.querySelectorAll('.name').forEach(function (element) {
      if (element.textContent !== profile.name) element.textContent = profile.name;
    });
    document.querySelectorAll('.fb-post-name').forEach(function (element) {
      if (element.textContent.trim() === 'User Name') element.textContent = profile.name;
    });
  }

  function applyBio(sourceProfile) {
    const value = String((sourceProfile || profile || {}).bio || '').trim();
    const element = document.querySelector('#profile .profileBioV150');
    if (!element) return;
    if (element.textContent !== value) element.textContent = value;
    const shouldShow = Boolean(value);
    if (element.classList.contains('has-bio') !== shouldShow) {
      element.classList.toggle('has-bio', shouldShow);
    }
  }

  window.__applySavedProfileBio = function (bio) {
    const value = String(bio || '').trim().slice(0, 101);
    if (profile) profile.bio = value;
    try { localStorage.setItem('profileBio', value); } catch (_error) {}
    cacheProfile();
    applyBio(profile || { bio: value });
  };

  function applyPhotos() {
    if (!profile) return;
    const avatar = profile.profilePhoto || fallbackAvatar;
    document.querySelectorAll('[data-home-avatar]:not(.fb-story-photo)').forEach(function (image) { image.src = avatar; });
    applyCreateStoryPhoto(avatar);
    const targetProfile = document.body.classList.contains('viewing-other-profile') ? (viewedProfile || profile) : profile;
    const profileComposerAvatar = document.querySelector('.app-page[data-page-content="profile"] .post-input-row .post-avatar img');
    if (profileComposerAvatar) {
      profileComposerAvatar.src = (targetProfile && targetProfile.profilePhoto) || fallbackAvatar;
      profileComposerAvatar.style.setProperty('object-fit', 'cover', 'important');
    }
    if (document.body.classList.contains('viewing-other-profile')) {
      applyFrames();
      return;
    }
    const mainPhoto = document.querySelector('#profile .avatar-default-photo');
    const avatarContainer = document.querySelector('#profile .avatar-container');
    if (mainPhoto) {
      mainPhoto.src = profile.profilePhoto || darkProfileDefaultAvatar;
      mainPhoto.style.setProperty('filter', profile.profilePhoto ? 'none' : 'brightness(0.22)', 'important');
      mainPhoto.style.setProperty('opacity', '1', 'important');
    }
    if (avatarContainer) {
      avatarContainer.classList.toggle('has-selected-profile-photo', Boolean(profile.profilePhoto));
    }
    if (profile.profilePhoto) document.body.dataset.hasCachedProfilePhoto = 'true';
    else delete document.body.dataset.hasCachedProfilePhoto;
    const cover = document.querySelector('#profile > .cover');
    if (cover && profile.coverPhoto) {
      cover.style.backgroundImage = 'url("' + profile.coverPhoto + '")';
    }
    applyFrames();
  }

  function frameAvatar(image) {
    if (!image || image.classList.contains('fb-story-photo')) return;
    let host = image.parentElement;
    if (!host || !host.classList.contains('fb-framed-avatar')) {
      const rect = image.getBoundingClientRect();
      const computed = getComputedStyle(image);
      host = document.createElement('span');
      host.className = 'fb-framed-avatar';
      host.style.width = computed.width !== 'auto' ? computed.width : Math.max(1, rect.width) + 'px';
      host.style.height = computed.height !== 'auto' ? computed.height : Math.max(1, rect.height) + 'px';
      image.parentNode.insertBefore(host, image);
      host.appendChild(image);
    }
    let overlay = host.querySelector(':scope > .fb-global-profile-frame');
    if (!overlay) {
      overlay = document.createElement('img');
      overlay.className = 'fb-global-profile-frame';
      overlay.alt = '';
      overlay.setAttribute('aria-hidden', 'true');
      host.appendChild(overlay);
    }
    overlay.src = profileFrameUrl();
    overlay.hidden = !profileFrameUrl();
  }

  function applyFrames() {
    if (!profile) return;
    const url = profileFrameUrl();
    const container = document.querySelector('#profile .avatar-container');
    if (container) {
      let overlay = container.querySelector(':scope > .fb-global-profile-frame');
      if (!overlay) {
        overlay = document.createElement('img');
        overlay.className = 'fb-global-profile-frame';
        overlay.alt = '';
        overlay.setAttribute('aria-hidden', 'true');
        container.appendChild(overlay);
      }
      overlay.src = url;
      overlay.hidden = !url;
      delete document.body.dataset.hasCachedProfileFrame;
      container.style.removeProperty('--fb-prepaint-frame');
    }
    document.querySelectorAll('[data-home-avatar]:not(.fb-story-photo),.stored-user-post .fb-post-avatar[data-current-user-avatar]').forEach(frameAvatar);
  }

  function applyCreateStoryPhoto(source) {
    const target = document.querySelector('.app-page[data-page-content="home"] .fb-create-story .fb-story-photo');
    if (!target || !source) return;
    const signature = source.length + ':' + source.slice(0, 64) + ':' + source.slice(-64);
    try {
      const cached = JSON.parse(localStorage.getItem('facebookCreateStoryPhotoCacheV2') || 'null');
      if (cached && cached.signature === signature && /^data:image\//.test(cached.image || '')) {
        target.src = cached.image;
        target.classList.remove('fb-prepaint-story-crop');
        if (typeof window.__markFacebookStoryReady === 'function') window.__markFacebookStoryReady(cached.image);
        return;
      }
    } catch (_error) {}

    if (!profile || !profile.profilePhoto) {
      target.src = source;
      target.classList.remove('fb-prepaint-story-crop');
      if (typeof window.__markFacebookStoryReady === 'function') window.__markFacebookStoryReady(source);
      return;
    }

    const image = new Image();
    image.onload = function () {
      try {
        const width = image.naturalWidth;
        const height = image.naturalHeight;
        const side = (Math.min(width, height) / Math.SQRT2) * 0.98;
        const output = document.createElement('canvas');
        const outputSize = Math.min(600, Math.max(320, Math.round(side)));
        output.width = outputSize;
        output.height = outputSize;
        output.getContext('2d', { alpha: false }).drawImage(
          image, (width - side) / 2, (height - side) / 2, side, side,
          0, 0, outputSize, outputSize
        );
        const result = output.toDataURL('image/jpeg', 0.84);
        target.src = result;
        target.classList.remove('fb-prepaint-story-crop');
        try { localStorage.setItem('facebookCreateStoryPhotoCacheV2', JSON.stringify({ signature: signature, image: result })); } catch (_error) {}
        if (window.__facebookPrepaintProfile) {
          window.__facebookPrepaintProfile.storyPhoto = result;
          window.__facebookPrepaintProfile.storyPhotoReady = true;
        }
        if (typeof window.__markFacebookStoryReady === 'function') window.__markFacebookStoryReady(result);
      } catch (_error) {
        target.src = source;
        target.classList.remove('fb-prepaint-story-crop');
        if (typeof window.__markFacebookStoryReady === 'function') window.__markFacebookStoryReady(source);
      }
    };
    image.onerror = function () {
      target.src = source;
      target.classList.remove('fb-prepaint-story-crop');
      if (typeof window.__markFacebookStoryReady === 'function') window.__markFacebookStoryReady(source);
    };
    image.src = source;
  }

  function readSavedPage() {
    try {
      const hashPage = (window.location.hash || '').replace(/^#/, '').toLowerCase();
      const page = supportedPages.has(hashPage) ? hashPage : (sessionStorage.getItem(pageStateKey) || localStorage.getItem(pageStateKey) || '');
      return supportedPages.has(page) ? page : '';
    } catch (_error) {
      return '';
    }
  }

  function savePage(page) {
    if (!supportedPages.has(page)) return;
    try { sessionStorage.setItem(pageStateKey, page); localStorage.setItem(pageStateKey, page); } catch (_error) {}
  }

  function readSavedViewedProfile() {
    try {
      const saved = JSON.parse(sessionStorage.getItem(viewedProfileStateKey) || 'null');
      return saved && saved.id ? saved : null;
    } catch (_error) {
      return null;
    }
  }

  function saveViewedProfile(user, isOwn) {
    try {
      if (isOwn || !user || !user.id) sessionStorage.removeItem(viewedProfileStateKey);
      else {
        const savedUser = Object.assign({}, user);
        delete savedUser._cachedPosts;
        sessionStorage.setItem(viewedProfileStateKey, JSON.stringify(savedUser));
      }
    } catch (_error) {}
  }

  function reelsFullscreenElement() {
    return document.fullscreenElement || document.webkitFullscreenElement || null;
  }

  function requestReelsBrowserFullscreen() {
    /* Reels now relies on the installed PWA standalone window instead of the
     * browser Fullscreen API. Chrome's fullscreen security notice cannot be
     * suppressed by a website, so never request browser fullscreen here. */
    return;
  }

  function exitReelsBrowserFullscreen() {
    if (!reelsFullscreenElement()) return;
    try {
      const exit = document.exitFullscreen || document.webkitExitFullscreen;
      if (!exit) return;
      const result = exit.call(document);
      if (result && typeof result.catch === 'function') result.catch(function () {});
    } catch (_error) {}
  }

  function restoreFeedPostControlsAfterReels() {
    document.body.classList.remove('is-reel-speed-hold');
    const reelRoot = document.querySelector('.app-page[data-page-content="reels"] .reels-page');
    if (reelRoot) reelRoot.classList.remove('is-reel-speed-hold', 'is-progress-dragging');

    document.querySelectorAll('.stored-user-post,.stored-profile-reel').forEach(function (article) {
      const actions = article.querySelector('.fb-post-actions');
      if (actions) {
        actions.hidden = false;
        actions.style.removeProperty('display');
        actions.style.removeProperty('visibility');
        actions.style.removeProperty('opacity');
        actions.style.removeProperty('pointer-events');
      }
      const id = String(article.dataset.postId || '');
      const post = postFeed.find(function (candidate) { return String(candidate && candidate.id || '') === id; });
      if (post) syncPostActionButtons(article, post);

      article.querySelectorAll('.fb-post-media-item').forEach(function (cell) {
        const video = cell.querySelector('video.fb-feed-autoplay-video, video[data-media-type="video"]');
        if (!video) return;
        let mute = cell.querySelector('.fb-feed-video-mute');
        if (!mute) mute = ensureFeedVideoMuteButton(cell, video);
        if (mute) {
          mute.hidden = false;
          mute.style.removeProperty('display');
          mute.style.removeProperty('visibility');
          mute.style.removeProperty('opacity');
          mute.style.removeProperty('pointer-events');
        }
        updateFeedVideoMuteButtonState(video);
      });
    });
  }

  function enforceProfileFeedControls() {
    if (document.body.dataset.page !== 'profile') return;
    const root = document.querySelector('.app-page[data-page-content="profile"]');
    if (!root) return;
    root.querySelectorAll('.stored-user-post,.stored-profile-reel').forEach(function (article) {
      const actions = article.querySelector('.fb-post-actions');
      if (actions) {
        actions.hidden = false;
        actions.removeAttribute('hidden');
        actions.style.setProperty('display', 'flex', 'important');
        actions.style.setProperty('visibility', 'visible', 'important');
        actions.style.setProperty('opacity', '1', 'important');
        actions.style.setProperty('pointer-events', 'auto', 'important');
        actions.querySelectorAll('.fb-action-button').forEach(function (button) {
          button.hidden = false;
          button.removeAttribute('hidden');
          button.style.setProperty('display', 'flex', 'important');
          button.style.setProperty('visibility', 'visible', 'important');
          button.style.setProperty('opacity', '1', 'important');
          button.style.setProperty('pointer-events', 'auto', 'important');
        });
      }
      article.querySelectorAll('.fb-post-media-item').forEach(function (cell) {
        const video = cell.querySelector('video.fb-feed-autoplay-video, video[data-media-type="video"]');
        if (!video) return;
        let mute = cell.querySelector('.fb-feed-video-mute');
        if (!mute) mute = ensureFeedVideoMuteButton(cell, video);
        if (mute) {
          mute.hidden = false;
          mute.removeAttribute('hidden');
          mute.style.setProperty('display', 'grid', 'important');
          mute.style.setProperty('visibility', 'visible', 'important');
          mute.style.setProperty('opacity', '1', 'important');
          mute.style.setProperty('pointer-events', 'auto', 'important');
        }
      });
    });
  }

  let profileControlsObserver = null;
  function installProfileControlsPersistence() {
    const root = document.querySelector('.app-page[data-page-content="profile"]');
    if (!root || profileControlsObserver) return;
    profileControlsObserver = new MutationObserver(function () {
      if (document.body.dataset.page === 'profile') enforceProfileFeedControls();
    });
    profileControlsObserver.observe(root, { childList: true, subtree: true, attributes: true, attributeFilter: ['hidden', 'style', 'class'] });
    enforceProfileFeedControls();
  }

  function setActivePage(page, resetScroll) {
    if (!supportedPages.has(page)) page = 'home';
    const previousPage = document.body.dataset.page || '';
    if (previousPage === 'reels' && page !== 'reels') clearReelsEntryContext();
    document.body.dataset.page = page;
    /* A delayed canplay/loadeddata callback from a hidden page must never
     * restart its video after navigation. Pause every player owned by another
     * app page immediately; the capture guard below also catches late starts. */
    document.querySelectorAll('.app-page video').forEach(function (video) {
      const owner = video.closest('.app-page[data-page-content]');
      if (owner && owner.dataset.pageContent !== page) {
        try { video.pause(); } catch (_error) {}
      }
    });
    if (page === 'reels') {
      requestReelsBrowserFullscreen();
      /* Reels owns playback while it is visible. Stop every Home/Profile feed
       * video immediately instead of waiting for IntersectionObserver to fire. */
      pauseFeedAutoplayVideos();
      /* Reels has its own internal snap scroller. The document itself must be
       * at the top or entering Reels from a scrolled Home/Profile page crops
       * the header and makes the selected Reel look like a broken fullscreen view. */
      try { window.scrollTo({ top: 0, left: 0, behavior: 'instant' }); } catch (_error) { window.scrollTo(0, 0); }
    }
    if (page !== 'reels') {
      exitReelsBrowserFullscreen();
      const reelRoot = document.querySelector('.app-page[data-page-content="reels"] .reels-page');
      const reelVideo = reelRoot && reelRoot.querySelector('#reelsVideo');
      if (reelVideo) { try { reelVideo.pause(); } catch (_error) {} }
      /* Leaving Reels can happen while the two-block handoff is still alive.
       * Tear that transient compositor state down now so returning from Home
       * can never reveal a neighbor/cover belonging to the previous session. */
      if (reelRoot && typeof reelRoot.__cleanupReelFeedNavigation === 'function') {
        try { reelRoot.__cleanupReelFeedNavigation(); } catch (_error) {}
      }
      restoreFeedPostControlsAfterReels();
      requestAnimationFrame(function () {
        restoreFeedPostControlsAfterReels();
        if (page === 'profile') rebuildProfileFeedAfterReels();
        requestAnimationFrame(function () {
          restoreFeedPostControlsAfterReels();
          if (page === 'profile') rebuildProfileFeedAfterReels();
        });
      });
    }
    if (page === 'home' || page === 'profile') scheduleFeedAutoplaySync();
    if (page === 'reels') installReels();
    if (typeof window.__facebookLoadActivePageData === 'function') {
      if (page === 'reels' && pendingReelOpen) {
        /* The exact Reel is already resolved by /api/reels/resolve. Do not let
           generic Reels hydration or saved-position restoration race it. The
           deep-open path refreshes the surrounding feed after first paint. */
        ++mainPageRestoreSerial;
      } else {
        window.__facebookLoadActivePageData(page).then(function(){
          restoreMainPageScroll(page);
        }).catch(function () {});
      }
    }
    document.querySelectorAll('.exact-bottom-nav .nav-item[data-page]').forEach(function (item) {
      const active = item.dataset.page === page;
      item.classList.toggle('is-active', active);
      item.classList.toggle('active', active);
      item.classList.toggle('profile-active', active && page === 'profile');
    });
    savePage(page);
    try { history.replaceState(cleanMainHistoryState(page), '', location.pathname + location.search + '#' + page); } catch (_error) {}
    if (page === 'home' && profile) {
      applyName();
      applyPhotos();
    }
    if (page === 'profile') {
      installProfileControlsPersistence();
      enforceProfileFeedControls();
      requestAnimationFrame(function () { enforceProfileFeedControls(); });
      setTimeout(enforceProfileFeedControls, 80);
      setTimeout(enforceProfileFeedControls, 260);
    }
    if (page === 'reels' && pendingReelOpen) {
      ++mainPageRestoreSerial;
    } else if (resetScroll && !mainPageScrollPositions.has(page)) window.scrollTo({ top: 0, behavior: 'instant' });
    else if (mainPageScrollPositions.has(page)) restoreMainPageScroll(page);
    if (page === 'reels') window.requestAnimationFrame(function () {
      const reelRoot = document.querySelector('.app-page[data-page-content="reels"] .reels-page');
      if (reelRoot && typeof reelRoot.__prepareReelsFreshEntry === 'function') {
        try { reelRoot.__prepareReelsFreshEntry(); } catch (_error) {}
      }
      /* When Home/Profile is opening a specific Reel, that Reel has already
       * been selected before the page switch. Do not start a second /api/reels
       * refresh here: its delayed native-pager reconciliation used to detach or
       * reload the playing video a few seconds later, causing the visible shrink,
       * pause and restart from 0:00. Normal navigation to Reels still refreshes. */
      if (!pendingReelOpen) loadLatestReel();
    });
  }
  window.__facebookSetActivePage = setActivePage;

  if (!window.__facebookPageScopedVideoGuardInstalled) {
    window.__facebookPageScopedVideoGuardInstalled = true;
    document.addEventListener('play', function (event) {
      const video = event.target;
      if (!video || video.tagName !== 'VIDEO') return;
      const owner = video.closest('.app-page[data-page-content]');
      if (owner && owner.dataset.pageContent !== document.body.dataset.page) {
        try { video.pause(); } catch (_error) {}
      }
    }, true);
  }


  ['fullscreenchange', 'webkitfullscreenchange'].forEach(function (eventName) {
    document.addEventListener(eventName, function () {
      if (document.body.dataset.page === 'reels') return;
      restoreFeedPostControlsAfterReels();
      if (document.body.dataset.page === 'profile') {
        requestAnimationFrame(rebuildProfileFeedAfterReels);
      }
    });
  });

  function syncProfileTotalPostCount(targetProfile) {
    const target = targetProfile || viewedProfile || profile;
    if (!target) return;
    const id = String(target.id || '');
    if (!id) return;
    const loadedPostCount = postFeed.filter(function (post) { return String(post && post.userId || '') === id; }).length;
    const loadedStandaloneReelCount = reelFeed.filter(function (reel) {
      return String(reel && reel.userId || '') === id && !String(reel && reel.sourcePostId || '');
    }).length;
    /* Profile totals come from PostgreSQL when available. The feed is intentionally
     * bounded for other users, so deriving the number only from currently loaded
     * cards can undercount badly. A Reel generated from a video post is not counted
     * a second time because it represents the same published post. */
    const authoritative = Number(target.contentCount);
    const total = Number.isFinite(authoritative)
      ? authoritative
      : Math.max(0, loadedPostCount + loadedStandaloneReelCount);
    const stats = document.querySelector('#profile .profileSecondaryStatsV125');
    const visitingOther = document.body.classList.contains('viewing-other-profile') && profile && String(id) !== String(profile.id || '');
    if (stats && visitingOther) {
      stats.innerHTML = '<strong>' + Math.max(0, Number(target.friendCount || 0)) + '</strong> friends <span class="profile-stat-dot">•</span> <strong>' + String(total) + '</strong> posts';
    } else {
      const count = stats ? stats.querySelector('strong') : document.querySelector('.profileSecondaryStatsV125 strong');
      if (count) count.textContent = String(total);
    }
    if (!Number.isFinite(Number(target.postCount))) target.postCount = loadedPostCount;
    if (!Number.isFinite(Number(target.reelCount))) target.reelCount = loadedStandaloneReelCount;
    try { localStorage.setItem('facebookProfilePostCountV1', String(total)); } catch (_error) {}
  }

  async function refreshProfileContentCount(targetProfile) {
    const target = targetProfile || viewedProfile || profile;
    if (!target || !target.id) return;
    try {
      const own = profile && String(target.id) === String(profile.id);
      const fresh = await api(own ? '/api/profile' : '/api/users/' + encodeURIComponent(target.id) + '/profile');
      if (!fresh) return;
      ['postCount','reelCount','contentCount'].forEach(function (key) {
        if (fresh[key] !== undefined && fresh[key] !== null) target[key] = Number(fresh[key]);
      });
      if (own && profile) {
        profile.postCount = target.postCount;
        profile.reelCount = target.reelCount;
        profile.contentCount = target.contentCount;
        cacheProfile();
      }
      syncProfileTotalPostCount(target);
    } catch (_error) {}
  }

  function rebuildProfileFeedAfterReels() {
    if (document.body.dataset.page !== 'profile') return;
    const profileSection = document.querySelector('#profile')?.parentElement?.querySelector('.posts-section');
    const targetProfile = viewedProfile || profile;
    if (!profileSection || !targetProfile) return;
    let posts = profileSection.querySelector('#profileStoredPosts');
    if (!posts) {
      posts = document.createElement('div');
      posts.id = 'profileStoredPosts';
      const emptyState = profileSection.querySelector('.empty-state');
      profileSection.insertBefore(posts, emptyState || null);
    }
    const ownPosts = postFeed.filter(function (post) { return String(post && post.userId || '') === String(targetProfile.id || ''); });
    posts.replaceChildren.apply(posts, ownPosts.map(postArticle));
    posts.hidden = profileSection.dataset.profileMediaTab === 'reels' || profileSection.dataset.profileMediaTab === 'photos';
    renderOwnerProfileReels();
    syncProfileTotalPostCount(targetProfile);
    restoreFeedPostControlsAfterReels();
  }

  function confirmFriendRemoval(person) {
    return new Promise(function (resolve) {
      const existing = document.querySelector('.fb-friend-remove-modal');
      if (existing) existing.remove();
      const name = String(person && person.name || 'this person');
      const overlay = document.createElement('div');
      overlay.className = 'fb-friend-remove-modal';
      document.body.classList.add('friend-remove-confirm-open');
      overlay.innerHTML = '<section class="fb-friend-remove-dialog" role="dialog" aria-modal="true" aria-labelledby="fbFriendRemoveTitle">' +
        '<h2 id="fbFriendRemoveTitle">Remove friend?</h2>' +
        '<p>Are you sure you want to remove <strong></strong> as a friend?</p>' +
        '<div class="fb-friend-remove-actions"><button type="button" class="fb-friend-remove-cancel">Cancel</button><button type="button" class="fb-friend-remove-confirm">Remove</button></div>' +
        '</section>';
      overlay.querySelector('strong').textContent = name;
      let finished = false;
      const finish = function (answer) {
        if (finished) return;
        finished = true;
        document.body.classList.remove('friend-remove-confirm-open');
        overlay.remove();
        resolve(Boolean(answer));
      };
      overlay.querySelector('.fb-friend-remove-cancel').addEventListener('click', function () { finish(false); });
      overlay.querySelector('.fb-friend-remove-confirm').addEventListener('click', function () { finish(true); });
      overlay.addEventListener('click', function (event) { if (event.target === overlay) finish(false); });
      document.body.appendChild(overlay);
    });
  }

  function ensureVisitorProfileActions() {
    const section = document.querySelector('.app-page[data-page-content="profile"] .action-buttons');
    if (!section) return null;
    let wrap = section.querySelector('.profile-visitor-actions');
    if (!wrap) {
      wrap = document.createElement('div');
      wrap.className = 'profile-visitor-actions';
      wrap.innerHTML = '<button type="button" class="profile-visitor-friend-btn"><img src="' + PROFILE_ACTION_ICONS.add + '" alt=""><span>Add friend</span></button>' +
        '<button type="button" class="profile-visitor-message-btn"><img src="' + PROFILE_ACTION_ICONS.message + '" alt=""><span>Message</span></button>';
      section.appendChild(wrap);
    }
    const messageIcon = wrap.querySelector('.profile-visitor-message-btn img');
    if (messageIcon && messageIcon.src !== PROFILE_ACTION_ICONS.message) messageIcon.src = PROFILE_ACTION_ICONS.message;
    if (wrap.dataset.actionsWired === 'true') return wrap;
    wrap.dataset.actionsWired = 'true';
    const friendButton = wrap.querySelector('.profile-visitor-friend-btn');
    friendButton.addEventListener('click', async function () {
      const user = viewedProfile;
      if (!user || !user.id || friendButton.disabled) return;
      friendButton.disabled = true;
      const previousState = String(user.friendState || 'none');
      try {
        const state = previousState;
        if (state === 'none') {
          user.friendState = 'requested';
          saveViewedProfile(user, false);
          syncVisitorProfileActions(user);
          await api('/api/friends/' + encodeURIComponent(user.id) + '/request', { method: 'POST', body: '{}' });
        } else if (state === 'requested') {
          user.friendState = 'none';
          saveViewedProfile(user, false);
          syncVisitorProfileActions(user);
          await api('/api/friends/' + encodeURIComponent(user.id) + '/request', { method: 'DELETE' });
        } else if (state === 'incoming' && user.friendRequestId) {
          await api('/api/friend-requests/' + encodeURIComponent(user.friendRequestId) + '/accept', { method: 'POST', body: '{}' });
          user.friendState = 'friends';
          user.friendRequestId = '';
          user.friendCount = Math.max(0, Number(user.friendCount || 0) + 1);
        } else if (state === 'friends') {
          const approved = await confirmFriendRemoval(user);
          if (!approved) return;
          await api('/api/friends/' + encodeURIComponent(user.id), { method: 'DELETE' });
          user.friendState = 'none';
          user.friendCount = Math.max(0, Number(user.friendCount || 0) - 1);
        }
        syncVisitorProfileActions(user);
        saveViewedProfile(user, false);
        loadFriendsPage(true).catch(function () {});
      } catch (error) {
        user.friendState = previousState;
        saveViewedProfile(user, false);
        syncVisitorProfileActions(user);
        message(error.message);
      } finally {
        friendButton.disabled = false;
      }
    });
    wrap.querySelector('.profile-visitor-message-btn').addEventListener('click', function () {
      window.dispatchEvent(new CustomEvent('facebookmessagerequest', { detail: { user: viewedProfile || null } }));
    });
    return wrap;
  }

  function syncVisitorProfileActions(user) {
    const wrap = ensureVisitorProfileActions();
    if (!wrap || !user) return;
    const friendButton = wrap.querySelector('.profile-visitor-friend-btn');
    const label = friendButton && friendButton.querySelector('span');
    const state = String(user.friendState || 'none');
    wrap.classList.add('is-ready');
    if (label) label.textContent = state === 'requested' ? 'Cancel request' : (state === 'incoming' ? 'Confirm' : (state === 'friends' ? 'Friends' : 'Add friend'));
    if (friendButton) {
      friendButton.dataset.friendState = state;
      const stateIcon = friendButton.querySelector('img');
      if (stateIcon) {
        stateIcon.src = state === 'friends' ? PROFILE_ACTION_ICONS.friends : (state === 'requested' ? PROFILE_ACTION_ICONS.cancel : PROFILE_ACTION_ICONS.add);
        stateIcon.style.filter = state === 'friends' ? 'brightness(0) invert(1)' : 'none';
      }
    }
    const stats = document.querySelector('#profile .profileSecondaryStatsV125');
    if (stats && document.body.classList.contains('viewing-other-profile')) {
      stats.innerHTML = '<strong>' + Math.max(0, Number(user.friendCount || 0)) + '</strong> friends <span class="profile-stat-dot">•</span> <strong>' + Math.max(0, Number(user.contentCount || 0)) + '</strong> posts';
    }
  }

  function profileFriendsCard() {
    return document.querySelector('.app-page[data-page-content="profile"] .friends-card');
  }

  function renderProfileFriendsCard(user, payload) {
    const card = profileFriendsCard();
    if (!card || !user) return;
    let head = card.querySelector('.profile-friends-head');
    let grid = card.querySelector('#profileFriendsGrid');
    if (!head) {
      head = document.createElement('div');
      head.className = 'profile-friends-head';
      const oldHeading = card.querySelector('h2');
      const oldSeeAll = card.querySelector('.view-all-link');
      if (oldHeading) head.appendChild(oldHeading);
      if (oldSeeAll) head.appendChild(oldSeeAll);
      card.prepend(head);
    }
    if (!grid) {
      grid = document.createElement('div');
      grid.id = 'profileFriendsGrid';
      grid.className = 'profile-friends-grid';
      card.appendChild(grid);
    }
    const totalCount = Math.max(0, Number(payload && payload.totalCount != null ? payload.totalCount : user.friendCount || 0));
    user.friendCount = totalCount;
    const heading = head.querySelector('h2');
    if (heading) heading.innerHTML = 'Friends' + (totalCount ? ' <span class="profile-friends-count">' + String(totalCount) + '</span>' : '');
    const friends = payload && Array.isArray(payload.friends) ? payload.friends : [];
    profileFriendsPayloadCache.set(String(user.id), { totalCount: totalCount, friends: friends.slice(0, 4) });
    grid.dataset.profileFriendsOwnerId = String(user.id);
    grid.dataset.profileFriendsResolved = 'true';
    grid.replaceChildren();
    if (!friends.length) {
      const empty = document.createElement('div');
      empty.className = 'profile-friends-empty';
      empty.textContent = totalCount ? 'Friends will appear here.' : 'No friends to show.';
      grid.appendChild(empty);
    } else {
      friends.slice(0, 4).forEach(function (friend) {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'profile-friend-tile';
        item.dataset.userId = String(friend.id || '');
        const avatarWrap = document.createElement('span');
        avatarWrap.className = 'profile-friend-avatar-wrap';
        const avatar = document.createElement('img');
        avatar.className = 'profile-friend-avatar';
        avatar.alt = friend.name || 'Friend';
        avatar.src = friend.profilePhoto || fallbackAvatar;
        avatarWrap.appendChild(avatar);
        if (friend.isOnline) {
          const online = document.createElement('span');
          online.className = 'profile-friend-online-dot';
          online.setAttribute('aria-label', 'Online');
          avatarWrap.appendChild(online);
        }
        const name = document.createElement('span');
        name.className = 'profile-friend-name';
        name.textContent = friend.name || 'Facebook user';
        const mutual = document.createElement('span');
        mutual.className = 'profile-friend-mutual';
        const mutualCount = Math.max(0, Number(friend.mutualCount || 0));
        mutual.textContent = mutualCount ? mutualCount + ' mutual friend' + (mutualCount === 1 ? '' : 's') : '';
        item.append(avatarWrap, name, mutual);
        item.addEventListener('click', function () { openUserProfile(friend.id); });
        grid.appendChild(item);
      });
    }
    const seeAll = head.querySelector('.view-all-link');
    if (seeAll) {
      seeAll.setAttribute('role', 'button');
      seeAll.setAttribute('href', '#');
      if (seeAll.dataset.profileFriendsReady !== 'true') {
        seeAll.dataset.profileFriendsReady = 'true';
        seeAll.addEventListener('click', function (event) {
          event.preventDefault();
          event.stopPropagation();
          if (profile && String(user.id) === String(profile.id)) {
            friendsPageView = 'friends';
            setActivePage('friends', true);
            loadFriendsPage(true).catch(function () {});
          }
        });
      }
    }
  }

  function loadProfileFriendsFor(user) {
    if (!user || !user.id) return;
    const serial = ++profileFriendsLoadSerial;
    const card = profileFriendsCard();
    if (card) card.classList.add('is-loading-friends');
    api('/api/users/' + encodeURIComponent(user.id) + '/friends?limit=4').then(function (payload) {
      if (serial !== profileFriendsLoadSerial) return;
      const active = document.body.classList.contains('viewing-other-profile') ? viewedProfile : profile;
      if (!active || String(active.id) !== String(user.id)) return;
      if (profile && String(user.id) === String(profile.id) && payload && Array.isArray(payload.friends)) {
        friendsPageData.friends = payload.friends.concat((friendsPageData.friends || []).filter(function (cached) {
          return !payload.friends.some(function (friend) { return String(friend.id) === String(cached.id); });
        }));
        friendsPageData.onlineFriends = friendsPageData.friends.filter(function (friend) { return friend.isOnline; });
        writeFriendsPageCache();
      }
      renderProfileFriendsCard(active, payload || {});
      if (card) card.classList.remove('is-loading-friends');
    }).catch(function () {
      if (serial !== profileFriendsLoadSerial) return;
      const fallbackFriends = profile && String(user.id) === String(profile.id) ? (friendsPageData.friends || []).slice(0, 4) : [];
      if (fallbackFriends.length || !card || !card.querySelector('.profile-friend-tile')) {
        renderProfileFriendsCard(user, { totalCount: user.friendCount || fallbackFriends.length, friends: fallbackFriends });
      }
      if (card) card.classList.remove('is-loading-friends');
    });
  }

  function installProfileFriendsPersistence() {
    if (profileFriendsPersistenceInstalled) return;
    profileFriendsPersistenceInstalled = true;
    const keepVisible = function () {
      if (document.body.dataset.page !== 'profile') return;
      const user = document.body.classList.contains('viewing-other-profile') ? viewedProfile : profile;
      const grid = document.querySelector('.app-page[data-page-content="profile"] #profileFriendsGrid');
      if (!user || !user.id || !grid) return;
      const userId = String(user.id);
      if (grid.querySelector('.profile-friend-tile') && grid.dataset.profileFriendsOwnerId === userId) return;
      let payload = profileFriendsPayloadCache.get(userId);
      if (!payload && profile && userId === String(profile.id)) {
        let people = (friendsPageData.friends || []).slice(0, 4);
        if (!people.length) {
          const cached = readFriendsPageCache();
          if (cached && Array.isArray(cached.friends)) {
            friendsPageData = cached;
            friendsPageLoaded = true;
            people = cached.friends.slice(0, 4);
          }
        }
        if (people.length) payload = { totalCount: Math.max(Number(user.friendCount || 0), people.length), friends: people };
      }
      if (payload && payload.friends && payload.friends.length) {
        renderProfileFriendsCard(user, payload);
        return;
      }
      const now = Date.now();
      if (grid.dataset.profileFriendsResolved !== 'true' && now - profileFriendsLastEnsureAt > 1200) {
        profileFriendsLastEnsureAt = now;
        loadProfileFriendsFor(user);
      }
    };
    const card = profileFriendsCard();
    if (card) new MutationObserver(function () { queueMicrotask(keepVisible); }).observe(card, { childList: true, subtree: true });
    window.setInterval(keepVisible, 700);
    keepVisible();
  }

  function renderViewedProfileIdentity(user) {
    if (!user) return;
    viewedProfile = user;
    window.__facebookDisplayedProfile = user;
    const isOwn = profile && String(user.id) === String(profile.id);
    saveViewedProfile(user, isOwn);
    document.body.classList.toggle('viewing-other-profile', !isOwn);
    /* Profile-detail listeners must see the correct owner/visitor state immediately.
     * Previously the event fired before viewing-other-profile was applied, so another
     * user's details could briefly/incorrectly render from the signed-in user's local data. */
    window.dispatchEvent(new CustomEvent('displayedprofilechange', { detail: user }));
    if (!isOwn) syncVisitorProfileActions(user);
    else {
      const stats = document.querySelector('#profile .profileSecondaryStatsV125');
      if (stats) stats.innerHTML = '<strong>' + Math.max(0, Number(user.contentCount || 0)) + '</strong> posts';
    }
    const name = document.querySelector('#profile .profileTextDetailsV125 .name,#profile .name');
    if (name) name.textContent = user.name || 'Facebook user';
    applyBio(user);
    const photo = document.querySelector('#profile .avatar-default-photo');
    if (photo) {
      photo.src = user.profilePhoto || (isOwn ? darkProfileDefaultAvatar : fallbackAvatar);
      photo.style.setProperty('filter', user.profilePhoto || !isOwn ? 'none' : 'brightness(0.22)', 'important');
      photo.style.setProperty('opacity', '1', 'important');
    }
    const avatarContainer = document.querySelector('#profile .avatar-container');
    if (avatarContainer) avatarContainer.classList.toggle('has-selected-profile-photo', Boolean(user.profilePhoto));
    const profileComposerAvatar = document.querySelector('.app-page[data-page-content="profile"] .post-input-row .post-avatar img');
    if (profileComposerAvatar) {
      profileComposerAvatar.src = user.profilePhoto || fallbackAvatar;
      profileComposerAvatar.style.setProperty('object-fit', 'cover', 'important');
    }
    const cover = document.querySelector('#profile > .cover');
    if (cover) cover.style.setProperty('background-image', user.coverPhoto ? 'url("' + user.coverPhoto + '")' : 'none', 'important');
    if (avatarContainer) {
      let frame = avatarContainer.querySelector(':scope > .fb-global-profile-frame');
      if (!frame) {
        frame = document.createElement('img');
        frame.className = 'fb-global-profile-frame';
        frame.alt = '';
        frame.setAttribute('aria-hidden', 'true');
        avatarContainer.appendChild(frame);
      }
      frame.src = user.profileFrameSvg ? 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(user.profileFrameSvg) : '';
      frame.hidden = !user.profileFrameSvg;
    }
    syncProfileTotalPostCount(user);
    loadProfileFriendsFor(user);
    renderOwnerProfileReels();
    const profileSection = document.querySelector('#profile')?.parentElement?.querySelector('.posts-section');
    if (profileSection) {
      let posts = profileSection.querySelector('#profileStoredPosts');
      if (!posts) {
        posts = document.createElement('div');
        posts.id = 'profileStoredPosts';
        profileSection.appendChild(posts);
      }
      const livePosts = postFeed.filter(function (post) { return String(post.userId) === String(user.id); });
      const userPosts = livePosts.length ? livePosts : (Array.isArray(user._cachedPosts) ? user._cachedPosts : []);
      posts.replaceChildren.apply(posts, userPosts.map(postArticle));
      posts.hidden = profileSection.dataset.profileMediaTab === 'reels';
    }
  }

  async function openUserProfile(userId) {
    const id = String(userId || '');
    if (!id) return;
    const savedUser = readSavedViewedProfile();
    const matchingSavedUser = savedUser && String(savedUser.id) === id ? savedUser : null;
    if (!matchingSavedUser) {
      try { sessionStorage.setItem(viewedProfileStateKey, JSON.stringify({ id: id })); } catch (_error) {}
    }
    const cachedReel = reelFeed.find(function (reel) { return String(reel.userId) === id; });
    const cachedPost = postFeed.find(function (post) { return String(post.userId) === id; });
    const cachedUser = profile && id === String(profile.id)
      ? Object.assign({}, profile)
      : Object.assign({
          id: id,
          name: (cachedReel && cachedReel.author) || (cachedPost && cachedPost.author) || 'Facebook user',
          profilePhoto: (cachedReel && cachedReel.profilePhoto) || (cachedPost && cachedPost.profilePhoto) || '',
          coverPhoto: '',
          profileFrameName: '',
          profileFrameSvg: ''
        }, matchingSavedUser || {});
    if (!Number.isFinite(Number(cachedUser.postCount))) cachedUser.postCount = postFeed.filter(function (post) { return String(post.userId) === id; }).length;
    if (!Number.isFinite(Number(cachedUser.reelCount))) cachedUser.reelCount = reelFeed.filter(function (reel) { return String(reel.userId) === id && !String(reel.sourcePostId || ''); }).length;
    renderViewedProfileIdentity(cachedUser);
    setActivePage('profile', true);
    let networkRendered = false;
    readCachedProfileView(id).then(function (cachedProfile) {
      if (!networkRendered && cachedProfile && viewedProfile && String(viewedProfile.id) === id) renderViewedProfileIdentity(cachedProfile);
    });
    try {
      const user = await api(profile && id === String(profile.id) ? '/api/profile' : '/api/users/' + encodeURIComponent(id) + '/profile');
      networkRendered = true;
      const userPosts = postFeed.filter(function (post) { return String(post.userId) === id; });
      user._cachedPosts = userPosts;
      renderViewedProfileIdentity(user);
      cacheProfileView(user, userPosts);
    } catch (error) {
      message(error.message);
    }
  }

  window.__facebookOpenUserProfile = openUserProfile;

  function makeProfileLink(element, userId) {
    if (!element || !userId) return;
    element.setAttribute('role', 'link');
    element.setAttribute('tabindex', '0');
    const open = function (event) {
      event.preventDefault();
      event.stopPropagation();
      openUserProfile(userId);
    };
    element.addEventListener('click', open);
    element.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' || event.key === ' ') open(event);
    });
  }

  function ensureGlobalSearchPage() {
    let page = document.getElementById('facebookGlobalSearchPage');
    if (page) return page;
    page = document.createElement('section');
    page.id = 'facebookGlobalSearchPage';
    page.className = 'fb-global-search-page';
    page.setAttribute('aria-hidden', 'true');
    page.innerHTML = '<header class="fb-global-search-head"><button type="button" data-global-search-back aria-label="Back">‹</button><label><input type="search" autocomplete="off" placeholder="Search" aria-label="Search"></label></header><main class="fb-global-search-results" aria-live="polite"></main>';
    const style = document.createElement('style');
    style.id = 'facebookGlobalSearchStyles';
    style.textContent = '.fb-global-search-page{position:fixed;inset:0;z-index:2147483600;background:#fff;color:#050505;display:none;overflow-y:auto;overscroll-behavior:contain}.fb-global-search-page.is-open{display:block}.fb-global-search-head{position:sticky;top:0;z-index:2;height:50px;background:#fff;border-bottom:1px solid #e4e6eb;display:flex;align-items:center;padding:0 3px 0 48px}.fb-global-search-head>button{position:absolute;left:9px;top:4px;width:39px;height:42px;border:0;background:transparent;color:#050505;font:300 44px/40px Arial;padding:0 0 3px 7px;text-align:left}.fb-global-search-head label{width:100%;height:34px;border-radius:18px;background:#f0f2f5;display:flex;align-items:center;padding:0 16px}.fb-global-search-head input{min-width:0;flex:1;border:0;outline:0;background:transparent;font-size:17px;font-weight:500;color:#050505}.fb-global-search-results{padding:5px 0 70px}.fb-global-search-section h2{font-size:20px;margin:16px 16px 8px}.fb-global-search-user,.fb-global-search-post{width:100%;border:0;background:#fff;color:#050505;text-align:left;display:flex;gap:12px;padding:10px 16px;align-items:center}.fb-global-search-user:active,.fb-global-search-post:active{background:#f0f2f5}.fb-global-search-user img,.fb-global-search-post img{width:48px;height:48px;border-radius:50%;object-fit:cover;background:#e4e6eb;flex:0 0 48px}.fb-global-search-user span,.fb-global-search-post span{min-width:0;display:flex;flex-direction:column;gap:3px}.fb-global-search-user strong,.fb-global-search-post strong{font-size:16px;font-weight:600}.fb-global-search-user small,.fb-global-search-post small{font-size:13px;color:#65676b}.fb-global-search-post p{font-size:15px;line-height:1.3;margin:1px 0 0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.fb-global-search-empty{padding:34px 18px;text-align:center;color:#65676b;font-size:15px}.fb-global-search-recent-head{display:flex;align-items:center;justify-content:space-between;margin:14px 16px 6px}.fb-global-search-recent-head h2{font-size:20px;margin:0}.fb-global-search-recent{height:48px;width:100%;border:0;background:#fff;display:grid;grid-template-columns:1fr 42px;align-items:center;padding:0 6px 0 16px;text-align:left;font-size:16px;color:#050505}.fb-global-search-recent>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fb-global-search-recent-x{width:38px;height:38px;border:0;background:transparent;border-radius:50%;font-size:28px;font-weight:300;line-height:36px;color:#65676b}body.fb-global-search-open{overflow:hidden!important}';
    style.textContent += '.fb-global-search-head{padding-left:44px!important;padding-right:0!important}.fb-global-search-head>button{left:9px!important;width:35px!important}';
    document.head.appendChild(style);
    document.body.appendChild(page);
    const input = page.querySelector('input');
    const results = page.querySelector('.fb-global-search-results');
    let timer = 0;
    let requestNumber = 0;
    function recentKey() { return 'facebookRecentSearchesV1:' + String(profile && profile.id || 'current'); }
    function readRecentSearches() {
      try {
        const values = JSON.parse(localStorage.getItem(recentKey()) || '[]');
        return Array.isArray(values) ? values.map(String).filter(Boolean).slice(0, 10) : [];
      } catch (_error) { return []; }
    }
    function writeRecentSearches(values) {
      try { localStorage.setItem(recentKey(), JSON.stringify(values.slice(0, 10))); } catch (_error) {}
    }
    function rememberSearch(query) {
      const clean = String(query || '').trim();
      if (!clean) return;
      writeRecentSearches([clean].concat(readRecentSearches().filter(function (value) { return value.toLowerCase() !== clean.toLowerCase(); })));
    }
    function renderRecentSearches() {
      results.replaceChildren();
      const values = readRecentSearches();
      if (!values.length) return;
      const header = document.createElement('div');
      header.className = 'fb-global-search-recent-head';
      const title = document.createElement('h2');
      title.textContent = 'Recent searches';
      header.appendChild(title);
      results.appendChild(header);
      values.forEach(function (value) {
        const row = document.createElement('div');
        row.className = 'fb-global-search-recent';
        const text = document.createElement('span');
        text.textContent = value;
        text.setAttribute('role', 'button');
        text.setAttribute('tabindex', '0');
        const remove = document.createElement('button');
        remove.type = 'button';
        remove.className = 'fb-global-search-recent-x';
        remove.setAttribute('aria-label', 'Remove ' + value + ' from recent searches');
        remove.textContent = '×';
        const select = function () { input.value = value; runSearch(); };
        text.addEventListener('click', select);
        text.addEventListener('keydown', function (event) { if (event.key === 'Enter' || event.key === ' ') select(); });
        remove.addEventListener('click', function () {
          writeRecentSearches(readRecentSearches().filter(function (entry) { return entry !== value; }));
          renderRecentSearches();
        });
        row.append(text, remove);
        results.appendChild(row);
      });
    }
    function close() {
      page.classList.remove('is-open');
      page.setAttribute('aria-hidden', 'true');
      document.body.classList.remove('fb-global-search-open');
    }
    function section(title) {
      const node = document.createElement('section');
      node.className = 'fb-global-search-section';
      const heading = document.createElement('h2');
      heading.textContent = title;
      node.appendChild(heading);
      return node;
    }
    async function runSearch() {
      const query = input.value.trim();
      const current = ++requestNumber;
      if (!query) {
        renderRecentSearches();
        return;
      }
      results.innerHTML = '<div class="fb-global-search-empty">Searching…</div>';
      try {
        const payload = await api('/api/search?q=' + encodeURIComponent(query) + '&scope=' + encodeURIComponent(page.dataset.searchScope || 'all'));
        if (current !== requestNumber) return;
        results.replaceChildren();
        const users = Array.isArray(payload.users) ? payload.users : [];
        const posts = Array.isArray(payload.posts) ? payload.posts : [];
        if (users.length) {
          const usersSection = section('People');
          users.forEach(function (user) {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'fb-global-search-user';
            const image = document.createElement('img');
            image.alt = '';
            image.src = user.profilePhoto || fallbackAvatar;
            image.onerror = function () { this.onerror = null; this.src = fallbackAvatar; };
            const copy = document.createElement('span');
            const name = document.createElement('strong');
            name.textContent = user.name || 'Facebook user';
            const id = document.createElement('small');
            id.textContent = 'User ID: ' + String(user.id || '');
            copy.append(name, id);
            button.append(image, copy);
            button.addEventListener('click', function () { rememberSearch(query); close(); openUserProfile(user.id); });
            usersSection.appendChild(button);
          });
          results.appendChild(usersSection);
        }
        if (page.dataset.searchScope !== 'users' && posts.length) {
          const postsSection = section('Posts');
          posts.forEach(function (post) {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'fb-global-search-post';
            const image = document.createElement('img');
            image.alt = '';
            image.src = post.profilePhoto || fallbackAvatar;
            image.onerror = function () { this.onerror = null; this.src = fallbackAvatar; };
            const copy = document.createElement('span');
            const author = document.createElement('strong');
            author.textContent = post.author || 'Facebook user';
            const body = document.createElement('p');
            body.textContent = post.body || 'Post';
            copy.append(author, body);
            button.append(image, copy);
            button.addEventListener('click', async function () {
              rememberSearch(query);
              close();
              await openUserProfile(post.userId);
              let attempts = 0;
              (function revealPost() {
                const target = document.querySelector('.stored-user-post[data-post-id="' + String(post.id) + '"]');
                if (target) {
                  target.scrollIntoView({ block: 'start', behavior: 'smooth' });
                  target.classList.add('fb-search-target-post');
                  setTimeout(function () { target.classList.remove('fb-search-target-post'); }, 1600);
                  return;
                }
                attempts += 1;
                if (attempts < 20) setTimeout(revealPost, 80);
              })();
            });
            postsSection.appendChild(button);
          });
          results.appendChild(postsSection);
        }
        if (!results.children.length) results.innerHTML = '<div class="fb-global-search-empty">No results found.</div>';
      } catch (error) {
        if (current !== requestNumber) return;
        results.innerHTML = '<div class="fb-global-search-empty"></div>';
        results.firstChild.textContent = error.message || 'Could not search right now.';
      }
    }
    page.querySelector('[data-global-search-back]').addEventListener('click', close);
    input.addEventListener('input', function () { clearTimeout(timer); timer = setTimeout(runSearch, 220); });
    input.addEventListener('keydown', function (event) { if (event.key === 'Enter' && input.value.trim()) rememberSearch(input.value); });
    page.__openSearch = function (scope) {
      page.dataset.searchScope = scope === 'users' ? 'users' : 'all';
      input.value = '';
      renderRecentSearches();
      page.classList.add('is-open');
      page.setAttribute('aria-hidden', 'false');
      document.body.classList.add('fb-global-search-open');
      requestAnimationFrame(function () { input.focus(); });
    };
    return page;
  }

  window.__facebookOpenGlobalSearch = function (scope) {
    ensureGlobalSearchPage().__openSearch(scope);
    return true;
  };

  document.addEventListener('click', function (event) {
    const profileSearchButton = event.target && event.target.closest && event.target.closest('[data-profile-action="search"],.app-page[data-page-content="profile"] img[alt="Search"]');
    if (!profileSearchButton) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    window.__facebookOpenGlobalSearch('all');
  }, true);

  const existingProfileSearch = document.querySelector('.app-page[data-page-content="profile"] img[alt="Search"]');
  if (existingProfileSearch) {
    existingProfileSearch.setAttribute('role', 'button');
    existingProfileSearch.setAttribute('tabindex', '0');
    existingProfileSearch.style.cursor = 'pointer';
    existingProfileSearch.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' || event.key === ' ') window.__facebookOpenGlobalSearch('all');
    });
  }


  function readFriendsPageCache() {
    try {
      const cached = JSON.parse(localStorage.getItem(friendsPageCacheKey) || 'null');
      if (!cached || typeof cached !== 'object') return null;
      return {
        suggestions: Array.isArray(cached.suggestions) ? cached.suggestions : [],
        requests: Array.isArray(cached.requests) ? cached.requests : [],
        friends: Array.isArray(cached.friends) ? cached.friends : [],
        onlineFriends: Array.isArray(cached.onlineFriends) ? cached.onlineFriends : [],
        onlineCount: Math.max(0, Number(cached.onlineCount || 0))
      };
    } catch (_error) { return null; }
  }

  function writeFriendsPageCache() {
    try { localStorage.setItem(friendsPageCacheKey, JSON.stringify(friendsPageData)); } catch (_error) {}
  }

  function friendsPageRoot() {
    return document.querySelector('.app-page[data-page-content="friends"] .fb-friends-page');
  }

  function friendsPagePeopleForSearch(query) {
    const needle = String(query || '').trim().toLowerCase();
    const rows = [];
    const seen = new Set();
    ['requests', 'suggestions', 'friends'].forEach(function (kind) {
      (friendsPageData[kind] || []).forEach(function (person) {
        const id = String(person && person.id || '');
        if (!id || seen.has(id)) return;
        if (needle && String(person.name || '').toLowerCase().indexOf(needle) < 0) return;
        seen.add(id);
        rows.push(Object.assign({}, person, { _friendsKind: kind }));
      });
    });
    return rows;
  }

  function friendActionButton(label, className, actionName, person, iconSrc) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = className;
    button.dataset.friendAction = actionName;
    button.dataset.friendUserId = String(person.id || '');
    if (person.requestId) button.dataset.friendRequestId = String(person.requestId);
    if (iconSrc) {
      const icon = document.createElement('img');
      icon.src = iconSrc;
      icon.alt = '';
      icon.setAttribute('aria-hidden', 'true');
      button.appendChild(icon);
    }
    const text = document.createElement('span');
    text.textContent = label;
    button.appendChild(text);
    return button;
  }

  function friendRowElement(person, kind) {
    const row = document.createElement('article');
    row.className = 'fb-friend-row';
    row.dataset.friendUserId = String(person.id || '');
    if (person.isOnline) row.classList.add('is-online');

    const avatar = document.createElement('button');
    avatar.type = 'button';
    avatar.className = 'fb-friend-avatar-link';
    avatar.setAttribute('aria-label', 'Open ' + (person.name || 'profile'));
    const image = document.createElement('img');
    image.alt = person.name || 'Profile photo';
    image.src = person.profilePhoto || fallbackAvatar;
    image.onerror = function () { this.onerror = null; this.src = fallbackAvatar; };
    avatar.appendChild(image);
    if (person.isOnline) {
      const dot = document.createElement('span');
      dot.className = 'fb-friend-avatar-online-dot';
      dot.setAttribute('aria-label', 'Online');
      avatar.appendChild(dot);
    }

    const main = document.createElement('div');
    main.className = 'fb-friend-row-main';
    const name = document.createElement('button');
    name.type = 'button';
    name.className = 'fb-friend-name';
    name.textContent = person.name || 'Facebook user';
    const actions = document.createElement('div');
    actions.className = 'fb-friend-actions';

    if (kind === 'requests') {
      actions.append(
        friendActionButton('Confirm', 'fb-friend-primary', 'accept', person, PROFILE_ACTION_ICONS.friends),
        friendActionButton('Delete', 'fb-friend-secondary', 'delete-request', person)
      );
    } else if (kind === 'friends' || kind === 'online') {
      actions.append(
        friendActionButton('Friends', 'fb-friend-secondary', 'unfriend', person, PROFILE_ACTION_ICONS.friends),
        friendActionButton('Message', 'fb-friend-message', 'message', person, PROFILE_ACTION_ICONS.message)
      );
    } else {
      const requested = String(person.friendState || '') === 'requested';
      actions.append(
        friendActionButton(requested ? 'Cancel request' : 'Add friend', requested ? 'fb-friend-primary is-requested' : 'fb-friend-primary', requested ? 'cancel-request' : 'add', person, requested ? PROFILE_ACTION_ICONS.cancel : PROFILE_ACTION_ICONS.add),
        friendActionButton('Remove', 'fb-friend-secondary', 'dismiss', person)
      );
    }

    const open = function () { if (person.id) openUserProfile(person.id); };
    avatar.addEventListener('click', open);
    name.addEventListener('click', open);
    main.append(name, actions);
    row.append(avatar, main);
    return row;
  }

  function friendsSection(titleText, people, kind, options) {
    const section = document.createElement('section');
    section.className = 'fb-friends-section';
    const heading = document.createElement('h2');
    heading.className = 'fb-friends-section-title';
    const title = document.createElement('span');
    title.textContent = titleText;
    heading.appendChild(title);
    if (options && options.requestCount !== undefined) {
      const count = document.createElement('span');
      count.className = 'fb-friend-request-count';
      count.textContent = String(options.requestCount);
      heading.appendChild(count);
    }
    if (options && options.onlineTitle) {
      const dot = document.createElement('span');
      dot.className = 'fb-friends-online-dot';
      dot.setAttribute('aria-hidden', 'true');
      heading.appendChild(dot);
    }
    section.appendChild(heading);
    const list = document.createElement('div');
    list.className = 'fb-friends-list';
    if (!people.length) {
      const empty = document.createElement('div');
      empty.className = 'fb-friend-empty';
      empty.textContent = options && options.emptyText ? options.emptyText : 'No people to show.';
      list.appendChild(empty);
    } else {
      people.forEach(function (person) { list.appendChild(friendRowElement(person, kind)); });
    }
    section.appendChild(list);
    return section;
  }

  function syncFriendsHeaderCounts() {
    const root = friendsPageRoot();
    if (!root) return;
    const requestCount = Math.max(0, Number((friendsPageData.requests || []).length));
    const requestBadge = root.querySelector('#fbFriendsRequestTabCount');
    if (requestBadge) {
      requestBadge.textContent = String(requestCount);
      requestBadge.hidden = requestCount < 1;
    }
    const onlineCount = root.querySelector('#fbFriendsOnlineCount');
    if (onlineCount) onlineCount.textContent = String(Math.max(0, Number(friendsPageData.onlineCount || 0)));
    updateNavigationBadges({ friendRequestCount: requestCount });
  }

  function renderFriendsPage() {
    const root = friendsPageRoot();
    if (!root) return;
    const content = root.querySelector('.fb-friends-content');
    if (!content) return;
    syncFriendsHeaderCounts();
    const searchInput = root.querySelector('#fbFriendsSearchInput');
    const searching = root.classList.contains('is-searching');
    content.replaceChildren();

    if (searching) {
      const people = friendsPagePeopleForSearch(searchInput && searchInput.value);
      content.appendChild(friendsSection('Search results', people, 'suggestions', { emptyText: 'No people found.' }));
      return;
    }

    if (friendsPageView === 'requests') friendsPageView = 'home';
    if (friendsPageView === 'home') {
      const requests = friendsPageData.requests || [];
      content.appendChild(friendsSection('Friend requests', requests, 'requests', {
        requestCount: requests.length,
        emptyText: 'No friend requests right now.'
      }));
      content.appendChild(friendsSection('People you may know', friendsPageData.suggestions || [], 'suggestions', {
        emptyText: 'No new suggestions right now.'
      }));
      return;
    }
    if (friendsPageView === 'friends') {
      content.appendChild(friendsSection('Your friends', friendsPageData.friends || [], 'friends', {
        emptyText: 'Your friends will appear here.'
      }));
      return;
    }
    if (friendsPageView === 'online') {
      content.appendChild(friendsSection('Online friends', friendsPageData.onlineFriends || [], 'online', {
        onlineTitle: true,
        emptyText: 'None of your friends are online right now.'
      }));
      return;
    }
    content.appendChild(friendsSection('People you may know', friendsPageData.suggestions || [], 'suggestions', {
      emptyText: 'No new suggestions right now.'
    }));
  }

  async function loadFriendsPage(force) {
    const root = friendsPageRoot();
    if (!root) return;
    if (!friendsPageLoaded) {
      const cached = readFriendsPageCache();
      if (cached) {
        friendsPageData = cached;
        friendsPageLoaded = true;
        renderFriendsPage();
      }
    }
    if (friendsPageLoading && !force) return friendsPageLoading;
    friendsPageLoading = api('/api/friends/overview').then(function (data) {
      friendsPageData = {
        suggestions: Array.isArray(data.suggestions) ? data.suggestions : [],
        requests: Array.isArray(data.requests) ? data.requests : [],
        friends: Array.isArray(data.friends) ? data.friends : [],
        onlineFriends: Array.isArray(data.onlineFriends) ? data.onlineFriends : [],
        onlineCount: Math.max(0, Number(data.onlineCount || 0))
      };
      friendsPageLoaded = true;
      writeFriendsPageCache();
      renderFriendsPage();
      return friendsPageData;
    }).catch(function (error) {
      if (!friendsPageLoaded) {
        const content = root.querySelector('.fb-friends-content');
        if (content) content.appendChild(friendsSection('Friends', [], 'friends', { emptyText: error.message || 'Could not load Friends.' }));
      }
      throw error;
    }).finally(function () { friendsPageLoading = null; });
    return friendsPageLoading;
  }

  function showFriendAcceptedState(button, userId) {
    const row = button && button.closest('.fb-friend-row');
    if (!row) return;
    row.classList.add('is-accepted');
    const actions = row.querySelector('.fb-friend-actions');
    if (actions) actions.hidden = true;
    let status = row.querySelector('.fb-friend-accepted-status');
    if (!status) {
      status = document.createElement('div');
      status.className = 'fb-friend-accepted-status';
      const text = document.createElement('span');
      text.textContent = 'You are now friends';
      status.appendChild(text);
      const main = row.querySelector('.fb-friend-row-main');
      if (main) main.appendChild(status);
    }
    const acceptedPerson = (friendsPageData.requests || []).find(function (person) { return String(person.id) === String(userId); });
    friendsPageData.requests = (friendsPageData.requests || []).filter(function (person) { return String(person.id) !== String(userId); });
    if (acceptedPerson && !(friendsPageData.friends || []).some(function (person) { return String(person.id) === String(userId); })) {
      friendsPageData.friends.unshift(Object.assign({}, acceptedPerson, { requestId: '', isOnline: Boolean(acceptedPerson.isOnline) }));
    }
    friendsPageData.onlineFriends = (friendsPageData.friends || []).filter(function (person) { return person.isOnline; });
    writeFriendsPageCache();
    syncFriendsHeaderCounts();
  }

  async function handleFriendAction(button) {
    const actionName = button.dataset.friendAction || '';
    const userId = button.dataset.friendUserId || '';
    const requestId = button.dataset.friendRequestId || '';
    if (!actionName || !userId) return;
    if (actionName === 'open-profile') { openUserProfile(userId); return; }
    if (actionName === 'message') {
      const person = ['suggestions', 'requests', 'friends', 'onlineFriends'].flatMap(function (kind) { return friendsPageData[kind] || []; }).find(function (entry) { return String(entry.id) === String(userId); }) || { id: userId };
      window.dispatchEvent(new CustomEvent('facebookmessagerequest', { detail: { user: person } }));
      return;
    }
    button.disabled = true;
    try {
      if (actionName === 'add') {
        const span = button.querySelector('span');
        if (span) span.textContent = 'Cancel request';
        const icon = button.querySelector('img');
        if (icon) icon.src = PROFILE_ACTION_ICONS.cancel;
        button.dataset.friendAction = 'cancel-request';
        button.classList.add('is-requested');
        const pendingPerson = (friendsPageData.suggestions || []).find(function (person) { return String(person.id) === String(userId); });
        if (pendingPerson) pendingPerson.friendState = 'requested';
        writeFriendsPageCache();
        await api('/api/friends/' + encodeURIComponent(userId) + '/request', { method: 'POST', body: '{}' });
        button.disabled = false;
        return;
      } else if (actionName === 'cancel-request') {
        const span = button.querySelector('span');
        if (span) span.textContent = 'Add friend';
        const icon = button.querySelector('img');
        if (icon) icon.src = PROFILE_ACTION_ICONS.add;
        button.dataset.friendAction = 'add';
        button.classList.remove('is-requested');
        const pendingPerson = (friendsPageData.suggestions || []).find(function (person) { return String(person.id) === String(userId); });
        if (pendingPerson) pendingPerson.friendState = 'none';
        writeFriendsPageCache();
        await api('/api/friends/' + encodeURIComponent(userId) + '/request', { method: 'DELETE' });
        button.disabled = false;
        return;
      } else if (actionName === 'dismiss') {
        await api('/api/friends/' + encodeURIComponent(userId) + '/dismiss', { method: 'POST', body: '{}' });
        friendsPageData.suggestions = friendsPageData.suggestions.filter(function (person) { return String(person.id) !== String(userId); });
      } else if (actionName === 'accept') {
        await api('/api/friend-requests/' + encodeURIComponent(requestId) + '/accept', { method: 'POST', body: '{}' });
        showFriendAcceptedState(button, userId);
        return;
      } else if (actionName === 'delete-request') {
        await api('/api/friend-requests/' + encodeURIComponent(requestId), { method: 'DELETE' });
        friendsPageData.requests = friendsPageData.requests.filter(function (person) { return String(person.requestId) !== String(requestId); });
      } else if (actionName === 'unfriend') {
        const friendPerson = (friendsPageData.friends || []).find(function (person) { return String(person.id) === String(userId); }) || {};
        if (!await confirmFriendRemoval(friendPerson)) { button.disabled = false; return; }
        await api('/api/friends/' + encodeURIComponent(userId), { method: 'DELETE' });
        const span = button.querySelector('span'); if (span) span.textContent = 'Add friend';
        const icon = button.querySelector('img'); if (icon) { icon.src = PROFILE_ACTION_ICONS.add; icon.style.filter = 'none'; }
        button.dataset.friendAction = 'add';
        button.classList.remove('is-requested', 'fb-friend-secondary');
        button.classList.add('fb-friend-primary');
        friendsPageData.friends = (friendsPageData.friends || []).filter(function (person) { return String(person.id) !== String(userId); });
        friendsPageData.onlineFriends = (friendsPageData.onlineFriends || []).filter(function (person) { return String(person.id) !== String(userId); });
        writeFriendsPageCache();
        button.disabled = false;
        return;
      }
      writeFriendsPageCache();
      renderFriendsPage();
    } catch (error) {
      const pendingPerson = (friendsPageData.suggestions || []).find(function (person) { return String(person.id) === String(userId); });
      if (actionName === 'add') {
        if (pendingPerson) pendingPerson.friendState = 'none';
        const span = button.querySelector('span'); if (span) span.textContent = 'Add friend';
        const icon = button.querySelector('img'); if (icon) icon.src = PROFILE_ACTION_ICONS.add;
        button.dataset.friendAction = 'add'; button.classList.remove('is-requested');
      } else if (actionName === 'cancel-request') {
        if (pendingPerson) pendingPerson.friendState = 'requested';
        const span = button.querySelector('span'); if (span) span.textContent = 'Cancel request';
        const icon = button.querySelector('img'); if (icon) icon.src = PROFILE_ACTION_ICONS.cancel;
        button.dataset.friendAction = 'cancel-request'; button.classList.add('is-requested');
      }
      writeFriendsPageCache();
      button.disabled = false;
      message(error.message);
    }
  }

  function installFriendsPage() {
    if (friendsPageInstalled) return;
    const root = friendsPageRoot();
    if (!root) return;
    friendsPageInstalled = true;
    const menuButton = root.querySelector('#fbFriendsMenuButton');
    const menu = root.querySelector('#fbFriendsMenuPopover');
    const searchButton = root.querySelector('#fbFriendsSearchButton');
    const searchBack = root.querySelector('#fbFriendsSearchBack');
    const searchInput = root.querySelector('#fbFriendsSearchInput');

    root.addEventListener('click', function (event) {
      const viewButton = event.target.closest('[data-friends-view]');
      if (viewButton) {
        friendsPageView = viewButton.dataset.friendsView || 'home';
        root.classList.remove('is-searching');
        if (menu) menu.hidden = true;
        renderFriendsPage();
        loadFriendsPage(false).catch(function () {});
        return;
      }
      const actionButton = event.target.closest('[data-friend-action]');
      if (actionButton) handleFriendAction(actionButton);
    });

    if (menuButton) menuButton.addEventListener('click', function (event) {
      event.stopPropagation();
      if (menu) menu.hidden = true;
      if (typeof window.__facebookOpenHomeAccountMenu === 'function') window.__facebookOpenHomeAccountMenu();
    });
    document.addEventListener('click', function (event) {
      if (menu && !menu.hidden && !event.target.closest('#fbFriendsMenuPopover,#fbFriendsMenuButton')) menu.hidden = true;
    });
    if (searchButton) searchButton.addEventListener('click', function () {
      window.__facebookOpenGlobalSearch('users');
    });
    if (searchBack) searchBack.addEventListener('click', function () {
      root.classList.remove('is-searching');
      if (searchInput) searchInput.value = '';
      renderFriendsPage();
    });
    if (searchInput) searchInput.addEventListener('input', renderFriendsPage);

    const cached = readFriendsPageCache();
    if (cached) {
      friendsPageData = cached;
      friendsPageLoaded = true;
      renderFriendsPage();
    }
  }

  function ensureNavigationBadges() {
    if (!document.getElementById('facebookNavigationBadgeStyles')) {
      const style = document.createElement('style');
      style.id = 'facebookNavigationBadgeStyles';
      style.textContent = '.exact-bottom-nav .nav-item[data-page]{position:relative}.fb-nav-request-badge{position:absolute;z-index:8;top:5px;left:calc(50% + 7px);min-width:17px;height:17px;padding:0 4px;border:2px solid #fff;border-radius:10px;background:#e41e3f;color:#fff;font:700 10px/13px Arial;text-align:center;box-sizing:border-box;pointer-events:none}.fb-nav-notification-dot{position:absolute;z-index:8;top:7px;left:calc(50% + 11px);width:10px;height:10px;border:2px solid #fff;border-radius:50%;background:#e41e3f;box-sizing:border-box;pointer-events:none}';
      document.head.appendChild(style);
    }
    const friendsItem = document.querySelector('.exact-bottom-nav .nav-item[data-page="friends"]');
    const notificationItem = document.querySelector('.exact-bottom-nav .nav-item[data-page="notifications"]');
    if (friendsItem && !friendsItem.querySelector('.fb-nav-request-badge')) {
      const badge = document.createElement('span');
      badge.className = 'fb-nav-request-badge';
      badge.hidden = true;
      badge.setAttribute('aria-label', 'Friend requests');
      friendsItem.appendChild(badge);
    }
    if (notificationItem && !notificationItem.querySelector('.fb-nav-notification-dot')) {
      const dot = document.createElement('span');
      dot.className = 'fb-nav-notification-dot';
      dot.hidden = true;
      dot.setAttribute('aria-label', 'Unread notifications');
      notificationItem.appendChild(dot);
    }
  }

  function updateNavigationBadges(counts) {
    ensureNavigationBadges();
    const requestBadge = document.querySelector('.fb-nav-request-badge');
    if (requestBadge && counts && counts.friendRequestCount !== undefined) {
      const count = Math.max(0, Number(counts.friendRequestCount || 0));
      requestBadge.textContent = count > 99 ? '99+' : String(count);
      requestBadge.hidden = count < 1;
    }
    const notificationDot = document.querySelector('.fb-nav-notification-dot');
    if (notificationDot && counts && counts.unreadNotificationCount !== undefined) {
      notificationDot.hidden = Math.max(0, Number(counts.unreadNotificationCount || 0)) < 1;
    }
  }

  async function loadNavigationBadges() {
    try {
      updateNavigationBadges(await api('/api/navigation-badges'));
    } catch (_error) {}
  }



  const marketplaceDefaultCategories=['Vehicles','Property rentals','Electronics','Home & garden','Apparel','Hobbies','Family','Entertainment','Sporting goods','Free stuff'];
  const marketplaceConditions=['New','Like new','Good','Fair'];
  function marketplaceLoadingMarkup(){return '<div class="fb-marketplace-loading" aria-label="Loading Marketplace"><div class="fb-friends-loading-row"><span></span><div><i></i><b></b></div></div><div class="fb-friends-loading-row"><span></span><div><i></i><b></b></div></div><div class="fb-friends-loading-row"><span></span><div><i></i><b></b></div></div></div>';}
  function readMarketplaceCache(key){try{const value=JSON.parse(sessionStorage.getItem(marketplacePageCacheKey+':'+key)||'null');if(!value||!Array.isArray(value.listings)||Date.now()-Number(value.savedAt||0)>90000)return null;return value;}catch(_error){return null;}}
  function writeMarketplaceCache(key,data){try{sessionStorage.setItem(marketplacePageCacheKey+':'+key,JSON.stringify(Object.assign({savedAt:Date.now()},data||{})));}catch(_error){}}
  function marketplaceRoot(){return document.querySelector('.app-page[data-page-content="marketplace"] .fb-marketplace-page');}
  function marketplaceFilterActive(){return Boolean(marketplaceFilters.category||marketplaceFilters.condition||marketplaceFilters.minPrice||marketplaceFilters.maxPrice);}
  function marketplaceFilterLabel(){const bits=[];if(marketplaceFilters.category)bits.push(marketplaceFilters.category);if(marketplaceFilters.condition)bits.push(marketplaceFilters.condition);if(marketplaceFilters.minPrice||marketplaceFilters.maxPrice)bits.push('Price');return bits.length?bits.join(' · '):'Filters';}
  function marketplaceSortLabel(){return {suggested:'Suggested',newest:'Date listed', 'price-low':'Price: low to high','price-high':'Price: high to low'}[marketplaceFilters.sort]||'Suggested';}
  function marketplaceEmptyMarkup(title,text,action){return '<div class="fb-marketplace-empty"><h3>'+escapeHtml(title)+'</h3><p>'+escapeHtml(text)+'</p>'+(action?'<button type="button" data-marketplace-empty-action>'+escapeHtml(action)+'</button>':'')+'</div>';}
  
  function protectMarketplaceHorizontalControls(root){
    if(!root || root.dataset.marketplaceSwipeProtected==='1') return;
    root.dataset.marketplaceSwipeProtected='1';
    const attach=function(row){
      if(!row||row.dataset.marketplacePan==='1')return;
      row.dataset.marketplacePan='1';
      let drag=null;
      row.addEventListener('touchstart',function(event){
        if(event.touches.length!==1)return;
        const t=event.touches[0];drag={x:t.clientX,y:t.clientY,left:row.scrollLeft,axis:''};
      },{passive:true});
      row.addEventListener('touchmove',function(event){
        if(!drag||event.touches.length!==1)return;
        const t=event.touches[0],dx=t.clientX-drag.x,dy=t.clientY-drag.y;
        if(!drag.axis&&Math.max(Math.abs(dx),Math.abs(dy))>4)drag.axis=Math.abs(dx)>Math.abs(dy)?'x':'y';
        if(drag.axis!=='x')return;
        row.scrollLeft=drag.left-dx;
        event.stopPropagation();
        if(event.cancelable)event.preventDefault();
      },{passive:false});
      row.addEventListener('touchend',function(){drag=null;},{passive:true});
      row.addEventListener('touchcancel',function(){drag=null;},{passive:true});
    };
    root.querySelectorAll('.fb-marketplace-nav,.fb-marketplace-filter-row,.fb-marketplace-categories').forEach(attach);
    root._attachMarketplacePan=attach;
  }

