    const shareMenu=document.createElement('div');shareMenu.className='fb-marketplace-share-menu';shareMenu.hidden=true;shareMenu.innerHTML='<div class="fb-marketplace-share-title">Share listing</div><button type="button" data-marketplace-share-target="home">Share to Home</button><button type="button" data-marketplace-share-target="profile">Share to Profile</button><button type="button" data-marketplace-share-target="story">Share to Story</button><button type="button" data-marketplace-share-target="copy">Copy link</button>';document.body.appendChild(shareMenu);
    const create=document.createElement('section');create.className='fb-marketplace-create';create.innerHTML='<header><button class="fb-marketplace-create-back" type="button" aria-label="Back"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 5 8 12l7 7"/></svg></button><h1>New listing</h1><button class="fb-marketplace-publish" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg><span>Publish</span></button></header><form><label class="fb-marketplace-photo-pick"><input type="file" accept="image/*" hidden data-marketplace-photo><span class="fb-marketplace-add-photo-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 6h4l1.5-2h5L16 6h4v14H4z"/><circle cx="12" cy="13" r="3.5"/></svg></span><span data-marketplace-photo-label>Add photo</span></label><label>Title<input type="text" maxlength="180" data-marketplace-title placeholder="What are you selling?"></label><label>Price<input type="number" min="0" step="0.01" inputmode="decimal" data-marketplace-price placeholder="0"></label><label>Category<select data-marketplace-category>'+marketplaceDefaultCategories.map(function(x){return '<option value="'+escapeHtml(x)+'">'+escapeHtml(x)+'</option>';}).join('')+'</select></label><label>Condition<select data-marketplace-condition><option value="">Select condition</option>'+marketplaceConditions.map(function(x){return '<option value="'+x+'">'+x+'</option>';}).join('')+'</select></label><label>Location<input type="text" maxlength="255" data-marketplace-create-location placeholder="City or area"></label><label>Description<textarea maxlength="4000" data-marketplace-description placeholder="Describe your item"></textarea></label></form>';document.body.appendChild(create);
    const filterSheet=document.createElement('div');filterSheet.className='fb-marketplace-popover fb-marketplace-filter-popover';filterSheet.hidden=true;filterSheet.innerHTML='<div class="fb-marketplace-popover-head"><strong>Filters</strong><button type="button" data-marketplace-popover-close aria-label="Close">×</button></div><label class="fb-marketplace-popover-field">Category<select data-marketplace-filter-category><option value="">All categories</option>'+marketplaceDefaultCategories.map(function(x){return '<option value="'+escapeHtml(x)+'">'+escapeHtml(x)+'</option>';}).join('')+'</select></label><label class="fb-marketplace-popover-field">Condition<select data-marketplace-filter-condition><option value="">Any condition</option>'+marketplaceConditions.map(function(x){return '<option value="'+x+'">'+x+'</option>';}).join('')+'</select></label><div class="fb-marketplace-popover-grid"><label>Min price<input type="number" min="0" inputmode="decimal" data-marketplace-min></label><label>Max price<input type="number" min="0" inputmode="decimal" data-marketplace-max></label></div><div class="fb-marketplace-popover-actions"><button type="button" data-marketplace-filter-clear>Clear</button><button type="button" class="is-primary" data-marketplace-filter-apply>Apply</button></div>';document.body.appendChild(filterSheet);
