    shell.querySelector('[data-marketplace-location-button]').addEventListener('click',function(){openMarketplaceLocationPicker();});
    shell.querySelector('[data-marketplace-sort]').addEventListener('click',function(event){event.stopPropagation();sortSheet.querySelectorAll('[data-marketplace-sort-value]').forEach(function(button){const selected=button.dataset.marketplaceSortValue===marketplaceFilters.sort;button.classList.toggle('is-selected',selected);button.querySelector('.fb-marketplace-sort-check').innerHTML=selected?'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m4.5 10 3.2 3.2 7.8-7.8"/></svg>':'';});openMarketplacePopover(sortSheet,event.currentTarget,245);});
    [filterSheet,sortSheet].forEach(function(pop){pop.addEventListener('click',function(event){if(event.target.closest('[data-marketplace-popover-close]'))closeMarketplacePopovers();});});
    document.addEventListener('click',function(event){if(!event.target.closest('.fb-marketplace-popover')&&!event.target.closest('[data-marketplace-filter]')&&!event.target.closest('[data-marketplace-sort]'))closeMarketplacePopovers();});
    filterSheet.querySelector('[data-marketplace-filter-clear]').addEventListener('click',function(){marketplaceFilters={category:'',condition:'',minPrice:'',maxPrice:'',sort:marketplaceFilters.sort||'suggested'};fillMarketplaceFilterSheet();updateMarketplaceFilterButtons();});
    filterSheet.querySelector('[data-marketplace-filter-apply]').addEventListener('click',function(){marketplaceFilters.category=filterSheet.querySelector('[data-marketplace-filter-category]').value;marketplaceFilters.condition=filterSheet.querySelector('[data-marketplace-filter-condition]').value;marketplaceFilters.minPrice=filterSheet.querySelector('[data-marketplace-min]').value;marketplaceFilters.maxPrice=filterSheet.querySelector('[data-marketplace-max]').value;closeMarketplacePopovers();updateMarketplaceFilterButtons();loadMarketplacePage(true);});
    sortSheet.addEventListener('click',function(event){const option=event.target.closest('[data-marketplace-sort-value]');if(!option)return;marketplaceFilters.sort=option.dataset.marketplaceSortValue;closeMarketplacePopovers();updateMarketplaceFilterButtons();loadMarketplacePage(true);});
    detail.addEventListener('click',function(event){if(event.target===detail){closeMarketplaceDetail();return;}const back=event.target.closest('[data-marketplace-view-back]');if(back){closeMarketplaceDetail();return;}const save=event.target.closest('[data-marketplace-detail-save]');if(save)toggleMarketplaceSave(save.dataset.marketplaceDetailSave,save);const share=event.target.closest('[data-marketplace-detail-share]');if(share){openMarketplaceShareMenu(detail._listing);return;}const edit=event.target.closest('[data-marketplace-edit]');if(edit){openMarketplaceEdit(detail._listing);detail.classList.remove('is-open');return;}const sold=event.target.closest('[data-marketplace-mark-sold]');if(sold)updateMarketplaceListingStatus(sold.dataset.marketplaceMarkSold,'sold');const remove=event.target.closest('[data-marketplace-delete]');if(remove)deleteMarketplaceListing(remove.dataset.marketplaceDelete);});

    let marketplaceMapboxPromise=null,marketplaceMap=null,marketplaceSelectedCountry='';
    function ensureMarketplaceMapbox(){
      if(window.mapboxgl)return Promise.resolve(window.mapboxgl);
      if(marketplaceMapboxPromise)return marketplaceMapboxPromise;
      marketplaceMapboxPromise=Promise.all([
        fetch('/api/mapbox-config',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject(new Error('Map is unavailable.'))),
        new Promise((resolve,reject)=>{
          let css=document.querySelector('link[data-marketplace-mapbox]');
          if(!css){css=document.createElement('link');css.rel='stylesheet';css.href='https://api.mapbox.com/mapbox-gl-js/v3.0.0/mapbox-gl.css';css.dataset.marketplaceMapbox='1';document.head.appendChild(css);}
          if(window.mapboxgl){resolve(window.mapboxgl);return;}
          let script=document.querySelector('script[data-marketplace-mapbox]');
          if(script){script.addEventListener('load',()=>resolve(window.mapboxgl),{once:true});script.addEventListener('error',()=>reject(new Error('Could not load map.')),{once:true});return;}
          script=document.createElement('script');script.src='https://api.mapbox.com/mapbox-gl-js/v3.0.0/mapbox-gl.js';script.dataset.marketplaceMapbox='1';script.onload=()=>resolve(window.mapboxgl);script.onerror=()=>reject(new Error('Could not load map.'));document.head.appendChild(script);
        })
      ]).then(([config,mapboxgl])=>{if(!config.accessToken)throw new Error('Map is not configured.');mapboxgl.accessToken=config.accessToken;return mapboxgl;});
      return marketplaceMapboxPromise;
    }
    async function openMarketplaceLocationPicker(){
      try{
        locationPicker.classList.add('is-open');
        marketplaceSelectedCountry='';
        locationPicker.querySelector('[data-marketplace-location-country]').textContent='Tap anywhere on the map';
        locationPicker.querySelector('[data-marketplace-location-use]').disabled=true;
        const mapboxgl=await ensureMarketplaceMapbox();
        const container=locationPicker.querySelector('[data-marketplace-location-map]');
        if(!marketplaceMap){
          marketplaceMap=new mapboxgl.Map({container,style:'mapbox://styles/mapbox/streets-v12',center:[10,25],zoom:1.5,attributionControl:false});
          marketplaceMap.addControl(new mapboxgl.NavigationControl({showCompass:false}),'top-right');
          marketplaceMap.on('click',async e=>{
            try{
              const data=await api('/api/mapbox/reverse?longitude='+encodeURIComponent(e.lngLat.lng)+'&latitude='+encodeURIComponent(e.lngLat.lat));
              const feature=data&&data.feature;
              const context=feature&&Array.isArray(feature.context)?feature.context:[];
              const countryContext=context.find(x=>String(x.id||'').indexOf('country.')===0);
              let country=countryContext&&countryContext.text||'';
              if(!country&&feature&&String(feature.id||'').indexOf('country.')===0)country=feature.text||'';
              if(!country&&feature&&feature.place_name)country=String(feature.place_name).split(',').pop().trim();
              if(!country)throw new Error('Choose another point.');
              marketplaceSelectedCountry=country;
              locationPicker.querySelector('[data-marketplace-location-country]').textContent=country;
              locationPicker.querySelector('[data-marketplace-location-use]').disabled=false;
            }catch(error){message(error.message||'Could not identify that location.');}
          });
        }else setTimeout(()=>marketplaceMap.resize(),40);
      }catch(error){locationPicker.classList.remove('is-open');message(error.message||'Could not open the map.');}
    }
    locationPicker.querySelector('[data-marketplace-location-close]').addEventListener('click',()=>locationPicker.classList.remove('is-open'));
    locationPicker.querySelector('[data-marketplace-location-use]').addEventListener('click',function(){
      if(!marketplaceSelectedCountry)return;
      marketplaceLocationCountry=marketplaceSelectedCountry;
      marketplacePageTab='location';
      locationPicker.classList.remove('is-open');
      loadMarketplacePage(true);
    });


