  function openMarketplaceCreate(){const page=document.querySelector('.fb-marketplace-create');if(!page)return;page.querySelector('form').reset();page._image='';page._editingId='';resetMarketplacePhotoPicker(page,'Add photo');const loc=marketplacePageData.location||'';page.querySelector('[data-marketplace-create-location]').value=loc;page.querySelector('h1').textContent='New listing';page.querySelector('.fb-marketplace-publish span').textContent='Publish';page.classList.remove('is-editing');page.classList.add('is-open');}
