  async function shareMarketplaceListing(target,item){
    const id=item&&item.id;if(!id)return;
    const url=marketplaceListingUrl(id);
    const price=item.price==null?'Free':[item.currency,Number(item.price).toLocaleString()].filter(Boolean).join(' ');
    const body='Marketplace: '+(item.title||'Listing')+' · '+price+'\n'+url;
    try{
      if(target==='copy'){await navigator.clipboard.writeText(url);message('Link copied');return;}
      if(target==='story'){
        const image=await marketplaceListingStoryImage(item);
        await api('/api/stories',{method:'POST',body:JSON.stringify({image:image,caption:(item.title||'Marketplace listing')+'\n'+url,visibility:'public'})});
        message('Shared to Story');return;
      }
      const listingEmbed={listingId:String(id),title:item.title||'Marketplace listing',price:item.price,currency:item.currency||'',location:item.location||'',sellerName:item.sellerName||'',status:item.status||'active'};
      await api('/api/posts',{method:'POST',body:JSON.stringify({body:'',visibility:'public',media:[],extras:{marketplaceListing:listingEmbed}})});
      if(target==='profile')setActivePage('profile',true);else setActivePage('home',true);
      if(typeof window.__facebookLoadActivePageData==='function')window.__facebookLoadActivePageData(target==='profile'?'profile':'home').catch(()=>{});
      message(target==='profile'?'Shared to Profile':'Shared to Home');
    }catch(error){message(error.message||'Could not share listing.');}
  }
  async function updateMarketplaceListingStatus(id,status){try{await api('/api/marketplace/'+encodeURIComponent(id)+'/status',{method:'PATCH',body:JSON.stringify({status:status})});const detail=document.querySelector('.fb-marketplace-detail');if(detail&&detail._listing)detail._listing.status=status;document.querySelectorAll('[data-marketplace-listing="'+CSS.escape(String(id))+'"]').forEach(function(card){card.classList.toggle('is-sold',status==='sold');let badge=card.querySelector('.fb-marketplace-sold-badge');if(status==='sold'&&!badge){badge=document.createElement('span');badge.className='fb-marketplace-sold-badge';badge.textContent='SOLD';card.querySelector('.fb-marketplace-card-media')?.appendChild(badge);}});if(detail){const button=detail.querySelector('[data-marketplace-mark-sold]');if(button){const label=button.querySelector('span:last-child');if(label)label.textContent='Sold';button.disabled=true;}}message(status==='sold'?'Marked as sold':'Listing updated');}catch(error){message(error.message);}}
  async function deleteMarketplaceListing(id){try{await api('/api/marketplace/'+encodeURIComponent(id),{method:'DELETE'});document.querySelector('.fb-marketplace-detail')?.classList.remove('is-open');loadMarketplacePage(true);message('Listing deleted');}catch(error){message(error.message);}}
  async function loadMarketplacePage(force){installMarketplacePage();const root=marketplaceRoot();if(!root)return[];const query=String(root.querySelector('.fb-marketplace-search-row input')?.value||'').trim();const params=new URLSearchParams({tab:marketplacePageTab,q:query,sort:marketplaceFilters.sort||'suggested'});if(marketplacePageTab==='location'&&marketplaceLocationCountry)params.set('country',marketplaceLocationCountry);if(marketplaceFilters.category)params.set('category',marketplaceFilters.category);if(marketplaceFilters.condition)params.set('condition',marketplaceFilters.condition);if(marketplaceFilters.minPrice)params.set('minPrice',marketplaceFilters.minPrice);if(marketplaceFilters.maxPrice)params.set('maxPrice',marketplaceFilters.maxPrice);const cacheKey=params.toString();if(!force&&!query){const cached=readMarketplaceCache(cacheKey);if(cached){renderMarketplacePage(cached);if(Date.now()-Number(cached.savedAt||0)<25000)return cached;}}if(marketplacePageLoading&&!force)return marketplacePageLoading;const content=root.querySelector('.fb-marketplace-content');if(!content.children.length)content.innerHTML=marketplaceLoadingMarkup();else if(force)content.classList.add('is-refreshing');marketplacePageLoading=api('/api/marketplace?'+params.toString()).then(function(data){renderMarketplacePage(data);if(!query)writeMarketplaceCache(cacheKey,data);return data;}).catch(function(error){content.innerHTML=marketplaceEmptyMarkup('Marketplace is unavailable',error.message||'Try again later.','');throw error;}).finally(function(){content.classList.remove('is-refreshing');marketplacePageLoading=null;});return marketplacePageLoading;}

  function notificationMessage(item) {
    if (item.type === 'post_like') return ' liked your post.';
    if (item.type === 'post_comment') return ' commented on your post.';
    if (item.type === 'mention') return ' mentioned you.';
    if (item.type === 'friend_request') return ' sent you a friend request.';
    if (item.type === 'friend_accept') return ' accepted your friend request.';
    return ' sent you a notification.';
  }

  function notificationsLoadingMarkup() {
    return '<div class="fb-notifications-loading" aria-label="Loading notifications"><div class="fb-friends-loading-row"><span></span><div><i></i><b></b></div></div><div class="fb-friends-loading-row"><span></span><div><i></i><b></b></div></div><div class="fb-friends-loading-row"><span></span><div><i></i><b></b></div></div></div>';
  }

  function installNotificationsPage() {
    if (notificationsPageInstalled) return;
    const page = document.querySelector('.app-page[data-page-content="notifications"]');
    if (!page) return;
    notificationsPageInstalled = true;
    const style = document.createElement('style');
    style.id = 'facebookNotificationsPageStyles';
    style.textContent = '.fb-notifications-page{min-height:calc(100dvh - 58px);padding-bottom:70px;background:#fff;color:#050505;font-family:Arial,Helvetica,sans-serif}.fb-notifications-header{position:sticky;top:0;z-index:3;height:68px;display:grid;grid-template-columns:38px minmax(0,1fr) 38px;align-items:center;gap:4px;padding:0 12px;border-bottom:1px solid #e4e6eb;background:#fff}.fb-notifications-header h1{margin:0;font:650 29px/36px Arial;letter-spacing:-.4px}.fb-notifications-list{padding:5px 0}.fb-notification-row{width:100%;min-height:76px;border:0;background:#fff;display:grid;grid-template-columns:58px minmax(0,1fr) 12px;gap:10px;align-items:center;padding:9px 14px;text-align:left;color:#050505;box-sizing:border-box;-webkit-tap-highlight-color:transparent}.fb-notification-row.is-unread{background:#e7f3ff}.fb-notification-row:active{background:#f0f2f5}.fb-notification-avatar{width:56px;height:56px;border-radius:50%;object-fit:cover;background:#e4e6eb}.fb-notification-copy{min-width:0;font:400 15px/20px Arial}.fb-notification-copy strong{font-weight:700}.fb-notification-comment-text{display:block;margin-top:2px;color:#65676b;font:400 14px/19px Arial;white-space:pre-wrap;overflow-wrap:anywhere}.fb-notification-time{display:block;margin-top:3px;color:#0866ff;font-size:13px;line-height:17px}.fb-notification-unread-dot{width:8px;height:8px;border-radius:50%;background:#0866ff}.fb-notification-row:not(.is-unread) .fb-notification-unread-dot{visibility:hidden}.fb-notification-request-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:9px}.fb-notification-request-actions button{height:34px;border:0;border-radius:8px;display:flex;align-items:center;justify-content:center;gap:6px;padding:0 10px;font:650 14px/34px Arial}.fb-notification-confirm{background:#0866ff;color:#fff}.fb-notification-confirm img{width:17px;height:17px;object-fit:contain;filter:brightness(0) invert(1)}.fb-notification-remove{background:#e4e6eb;color:#050505}.fb-notification-request-actions button:disabled{opacity:.6}.fb-notification-result{display:block;margin-top:7px;color:#31a24c;font:600 14px/18px Arial}.fb-notifications-empty,.fb-notifications-loading{padding:72px 22px;text-align:center;color:#65676b;font:400 15px/21px Arial}';
    style.textContent += '.fb-notification-time{color:#65676b!important}.fb-notifications-loading{padding:8px 14px!important;text-align:left!important}.fb-comments-page-comment.is-notification-target{background:transparent!important;box-shadow:none!important;border-radius:0!important}.fb-comments-page-comment.is-notification-target::before{content:"";position:absolute;z-index:0;left:-7px;right:-7px;top:6px;bottom:15px;border-radius:10px;background:#e7f3ff;pointer-events:none}.fb-comments-page-comment.is-notification-target>*{position:relative;z-index:1}';
    document.head.appendChild(style);
    page.replaceChildren();
    const shell = document.createElement('section');
    shell.className = 'fb-notifications-page';
    const header = document.createElement('header');
    header.className = 'fb-notifications-header';
    const title = document.createElement('h1');
    title.textContent = 'Notifications';
    const menuButton = document.createElement('button');
    menuButton.type = 'button';
    menuButton.className = 'fb-friends-icon-button';
    menuButton.setAttribute('aria-label', 'Notifications menu');
    menuButton.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M3 12h18M3 18h18"/></svg>';
    menuButton.addEventListener('click', function () { window.__facebookOpenHomeAccountMenu?.(); });
    const searchButton = document.createElement('button');
    searchButton.type = 'button';
    searchButton.className = 'fb-friends-icon-button';
    searchButton.setAttribute('aria-label', 'Search');
    searchButton.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg>';
    searchButton.addEventListener('click', function () { window.__facebookOpenGlobalSearch?.('all'); });
    const list = document.createElement('main');
    list.className = 'fb-notifications-list';
    list.innerHTML = notificationsLoadingMarkup();
    header.append(menuButton, title, searchButton);
    shell.append(header, list);
    page.appendChild(shell);
  }

  function renderNotifications(items) {
    installNotificationsPage();
    const list = document.querySelector('.fb-notifications-list');
    if (!list) return;
    list.replaceChildren();
    if (!items.length) {
      const empty = document.createElement('div');
      empty.className = 'fb-notifications-empty';
      empty.textContent = 'No notifications yet.';
      list.appendChild(empty);
      return;
    }
    items.forEach(function (item) {
      const row = document.createElement('article');
      row.className = 'fb-notification-row' + (item.unread ? ' is-unread' : '');
      row.setAttribute('role', 'button');
      row.setAttribute('tabindex', '0');
      const avatar = document.createElement('img');
      avatar.className = 'fb-notification-avatar';
      avatar.alt = '';
      avatar.src = item.actorProfilePhoto || fallbackAvatar;
      avatar.onerror = function () { this.onerror = null; this.src = fallbackAvatar; };
      const copy = document.createElement('span');
      copy.className = 'fb-notification-copy';
      const name = document.createElement('strong');
      name.textContent = item.actorName || 'Facebook user';
      copy.append(name, document.createTextNode(notificationMessage(item)));
      if ((item.type === 'post_comment' || item.type === 'mention') && item.detail) {
        const commentText = document.createElement('span');
        commentText.className = 'fb-notification-comment-text';
        commentText.textContent = '“' + String(item.detail) + '”';
        copy.appendChild(commentText);
      }
      const time = document.createElement('span');
      time.className = 'fb-notification-time';
      time.textContent = facebookFormatPostDate(item.createdAt) || 'Just now';
      copy.appendChild(time);
      if (item.type === 'friend_request' && item.friendRequestId) {
        const actions = document.createElement('span');
        actions.className = 'fb-notification-request-actions';
        const confirm = document.createElement('button');
        confirm.type = 'button';
        confirm.className = 'fb-notification-confirm';
        const confirmIcon = document.createElement('img');
        confirmIcon.src = PROFILE_ACTION_ICONS.friends;
        confirmIcon.alt = '';
        confirm.append(confirmIcon, document.createTextNode('Confirm'));
        const remove = document.createElement('button');
        remove.type = 'button';
        remove.className = 'fb-notification-remove';
        remove.textContent = 'Remove';
        confirm.addEventListener('click', async function (event) {
          event.stopPropagation();
          confirm.disabled = true;
          remove.disabled = true;
          try {
            await api('/api/friend-requests/' + encodeURIComponent(item.friendRequestId) + '/accept', { method: 'POST', body: '{}' });
            actions.remove();
            const result = document.createElement('span');
            result.className = 'fb-notification-result';
            result.textContent = 'You are now friends';
            copy.appendChild(result);
            friendsPageLoaded = false;
            loadFriendsPage(true).catch(function () {});
            loadNavigationBadges();
          } catch (error) {
            confirm.disabled = false;
            remove.disabled = false;
            message(error.message);
          }
        });
        remove.addEventListener('click', async function (event) {
          event.stopPropagation();
          confirm.disabled = true;
          remove.disabled = true;
          try {
            await api('/api/friend-requests/' + encodeURIComponent(item.friendRequestId), { method: 'DELETE' });
            row.remove();
            friendsPageLoaded = false;
            loadFriendsPage(true).catch(function () {});
            loadNavigationBadges();
          } catch (error) {
            confirm.disabled = false;
            remove.disabled = false;
            message(error.message);
          }
        });
        actions.append(confirm, remove);
        copy.appendChild(actions);
      }
      const dot = document.createElement('span');
      dot.className = 'fb-notification-unread-dot';
      row.append(avatar, copy, dot);
      const openNotification = async function () {
        if (item.unread) {
          item.unread = false;
          row.classList.remove('is-unread');
          api('/api/notifications/' + encodeURIComponent(item.id) + '/read', { method: 'POST', body: '{}' })
            .then(loadNavigationBadges)
            .catch(function () {});
        }
        if (item.postId && item.postOwnerId) {
          await openUserProfile(item.postOwnerId);
          if ((item.type === 'post_comment' || item.type === 'mention') && item.commentId) {
            const commentPost = postFeed.find(function (post) { return String(post.id) === String(item.postId); });
            if (commentPost) {
              await openCommentsPage('post', commentPost, item.commentId);
              return;
            }
          }
          window.setTimeout(function () {
            const post = document.querySelector('.stored-user-post[data-post-id="' + String(item.postId).replace(/[^0-9]/g, '') + '"]');
            if (post) post.scrollIntoView({ block: 'start', behavior: 'smooth' });
          }, 80);
        } else if (item.actorId) {
          openUserProfile(item.actorId);
        }
      };
      row.addEventListener('click', openNotification);
      row.addEventListener('keydown', function (event) { if (event.key === 'Enter' || event.key === ' ') openNotification(); });
      list.appendChild(row);
    });
  }

  async function loadNotificationsPage(markRead) {
    installNotificationsPage();
    if (notificationsPageLoading) return notificationsPageLoading;
    notificationsPageLoading = api('/api/notifications').then(async function (data) {
      const items = Array.isArray(data.notifications) ? data.notifications : [];
      renderNotifications(items);
      return items;
    }).catch(function (error) {
      const list = document.querySelector('.fb-notifications-list');
      if (list) list.innerHTML = '<div class="fb-notifications-empty"></div>';
      const empty = list && list.querySelector('.fb-notifications-empty');
      if (empty) empty.textContent = error.message || 'Could not load notifications.';
      throw error;
    }).finally(function () { notificationsPageLoading = null; });
    return notificationsPageLoading;
  }

  ensureNavigationBadges();
  installMarketplacePage();
  installNotificationsPage();
  loadNavigationBadges();
  window.setInterval(loadNavigationBadges, 30000);

  function installPresenceHeartbeat() {
    if (window.__facebookPresenceHeartbeatInstalled) return;
    window.__facebookPresenceHeartbeatInstalled = true;
    const ping = function () {
      if (document.visibilityState === 'hidden') return;
      api('/api/presence/ping', { method: 'POST', body: '{}' }).catch(function () {});
    };
    ping();
    window.setInterval(ping, 45000);
    document.addEventListener('visibilitychange', function () {
      if (document.visibilityState === 'visible') {
        ping();
        if (document.body.dataset.page === 'friends') loadFriendsPage(true).catch(function () {});
      }
    });
  }
  installPresenceHeartbeat();

  let mainPageSwipeInstalled = false;
  let suppressMainPageSwipeClickUntil = 0;

  function swipeTargetHasHorizontalScroller(target) {
    let node = target && target.nodeType === 1 ? target : null;
    while (node && node !== document.body) {
      if (node.classList && (node.classList.contains('app-page') || node.classList.contains('phone-preview'))) break;
      try {
        const style = getComputedStyle(node);
        if ((style.overflowX === 'auto' || style.overflowX === 'scroll') && node.scrollWidth > node.clientWidth + 8) return true;
      } catch (_error) {}
      node = node.parentElement;
    }
    return false;
  }

  function settingsSurfaceIsOpen() {
    if (document.body.classList.contains('fb-settings-refresh-locked')) return true;
    return Boolean(document.querySelector('#facebookSharedSettingsPage.is-open,#facebookAccountSettingsPage.is-open,#facebookSettingsSectionPage.is-open,#facebookAccountEditor.is-open,#facebookAdminUserPage.is-open,#facebookAdminActionPage.is-open,#facebookAdminActivityPage.is-open,#facebookSharedSettingsPage[aria-hidden="false"],#facebookAccountSettingsPage[aria-hidden="false"],#facebookSettingsSectionPage[aria-hidden="false"],#facebookAccountEditor[aria-hidden="false"],#facebookAdminUserPage[aria-hidden="false"],#facebookAdminActionPage[aria-hidden="false"],#facebookAdminActivityPage[aria-hidden="false"]'));
  }

  function mainPageSwipeBlocked(target) {
    /* Never let a horizontal main-page swipe steal an active Reel scrub. */
    if (document.body.classList.contains('is-reel-progress-dragging') || document.querySelector('.reels-page.is-progress-dragging')) return true;
    if (target && target.closest && target.closest('.fb-marketplace-nav,.fb-marketplace-filter-row,.fb-marketplace-search-row,.fb-marketplace-categories')) return true;

    if (settingsSurfaceIsOpen()) return true;
    if (document.body.classList.contains('fb-post-media-overlay-open')) return true;
    if (document.querySelector('#fbComposerOverlay.is-open,.fb-composer-photo-preview.is-open,.fb-composer-photo-editor.is-open,.fb-composer-video-preview-layer.is-open,.fb-comments-page.is-open,.reels-comments.open,.fb-story-viewer.is-open,.fb-post-media-viewer.is-open,.fb-post-media-page.is-open,#facebookPostMediaViewer.is-open,#facebookPostMediaGalleryPage.is-open,.fb-global-search-page.is-open')) return true;
    if (!target || !target.closest) return true;
    if (target.closest('.exact-bottom-nav,.fb-home-overlay,.fb-comments-page,.fb-story-viewer,.fb-home-account-layer,.fb-delete-dialog,.fb-post-media-viewer,.fb-post-media-page,.reel-create-flow,.reel-create-editor,.reels-library-page,.reels-search-panel,.reels-comments,.reels-options,.fb-composer-photo-editor-layer,[contenteditable="true"],input,textarea,select')) return true;
    if (target.closest('.reels-progress,.reel-edit-timeline,.fb-post-audio-track,.fb-music-card-progress-button,.fb-music-card-progress-bar,.fb-compose-wave-bars')) return true;
    return swipeTargetHasHorizontalScroller(target);
  }

  try {
    if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
  } catch (_error) {}

  const mainPageScrollPositions = new Map();
  const mainPageScrollStorageKey = 'facebookMainPagePositionsV3';
  const mainPageAnchorAttributes = [
    'data-post-id', 'data-marketplace-listing', 'data-notification-id',
    'data-friend-id', 'data-user-id', 'data-library-reel-id'
  ];
  let mainPageScrollSaveRaf = 0;
  let mainPageRestoreSerial = 0;
  let mainPageApplyingRestore = false;

  try {
    const savedPositions = JSON.parse(sessionStorage.getItem(mainPageScrollStorageKey) || '{}');
    Object.keys(savedPositions || {}).forEach(function (page) {
      if (supportedPages.has(page)) mainPageScrollPositions.set(page, savedPositions[page]);
    });
  } catch (_error) {}

  function persistMainPagePositions() {
    try {
      const data = {};
      mainPageScrollPositions.forEach(function (value, key) { data[key] = value; });
      sessionStorage.setItem(mainPageScrollStorageKey, JSON.stringify(data));
    } catch (_error) {}
  }

  function mainPageRoot(page) {
    return document.querySelector('.app-page[data-page-content="' + page + '"]');
  }

  function mainPageAnchorKey(element) {
    if (!element) return '';
    for (const attribute of mainPageAnchorAttributes) {
      const value = element.getAttribute && element.getAttribute(attribute);
      if (value) return attribute + ':' + value;
    }
    if (element.id) return 'id:' + element.id;
    return '';
  }

  function mainPageAnchorCandidates(root) {
    if (!root) return [];
    return root.querySelectorAll('[data-post-id],[data-marketplace-listing],[data-notification-id],[data-friend-id],[data-user-id],[data-library-reel-id],article[id]');
  }

  function captureMainPageAnchor(page) {
    const root = mainPageRoot(page);
    if (!root) return null;
    const candidates = mainPageAnchorCandidates(root);
    const viewportHeight = Math.max(1, window.innerHeight || document.documentElement.clientHeight || 1);
    let best = null;
    let bestDistance = Infinity;
    for (const element of candidates) {
      const rect = element.getBoundingClientRect();
      if (rect.bottom <= 0 || rect.top >= viewportHeight) continue;
      const key = mainPageAnchorKey(element);
      if (!key) continue;
      const distance = Math.abs(rect.top);
      if (distance < bestDistance) {
        bestDistance = distance;
        best = { key:key, offset:rect.top };
      }
    }
    return best;
  }

  function findMainPageAnchor(page, key) {
    if (!key) return null;
    const root = mainPageRoot(page);
    if (!root) return null;
    const candidates = mainPageAnchorCandidates(root);
    for (const element of candidates) {
      if (mainPageAnchorKey(element) === key) return element;
    }
    return null;
  }

  function rememberMainPageScroll(page) {
    if (!supportedPages.has(page)) return;
    if (page === 'reels') {
      mainPageScrollPositions.set(page, {
        reelIndex:Math.max(0, Number(currentReelIndex) || 0),
        reelId:currentReel && currentReel.id ? String(currentReel.id) : '',
        savedAt:Date.now()
      });
    } else {
      const anchor = captureMainPageAnchor(page);
      mainPageScrollPositions.set(page, {
        top:Math.max(0, window.scrollY || document.documentElement.scrollTop || 0),
        anchorKey:anchor && anchor.key || '',
        anchorOffset:anchor ? Number(anchor.offset) || 0 : 0,
        savedAt:Date.now()
      });
    }
    persistMainPagePositions();
  }

  function restoreMainPageScroll(page) {
    if (!supportedPages.has(page)) return;
    /* An exact Reel opened from Home/Profile is a deep-link. It must always
       beat the normal "return to my last Reels position" behavior. */
    if (page === 'reels' && pendingReelOpen) return;
    const saved = mainPageScrollPositions.get(page);
    if (!saved) return;
    const serial = ++mainPageRestoreSerial;

    if (page === 'reels') {
      const restoreReel = function () {
        if (pendingReelOpen) return;
        if (serial !== mainPageRestoreSerial || document.body.dataset.page !== 'reels') return;
        const root = document.querySelector('.app-page[data-page-content="reels"] .reels-page');
        if (!root || !reelFeed.length) return;
        let index = Number(saved.reelIndex);
        if (saved.reelId) {
          const found = reelFeed.findIndex(function (item) { return item && String(item.id || '') === String(saved.reelId); });
          if (found >= 0) index = found;
        }
        if (!Number.isFinite(index)) return;
        index = Math.max(0, Math.min(reelFeed.length - 1, index));
        currentReelIndex = index;
        const reel = reelFeed[index];
        if (reel) showReel(root, reel);
      };
      requestAnimationFrame(restoreReel);
      setTimeout(restoreReel, 100);
      return;
    }

    const apply = function () {
      if (serial !== mainPageRestoreSerial || document.body.dataset.page !== page) return;
      let targetTop = Math.max(0, Number(saved.top) || 0);
      const anchor = findMainPageAnchor(page, saved.anchorKey || '');
      if (anchor) {
        const documentTop = (window.scrollY || document.documentElement.scrollTop || 0) + anchor.getBoundingClientRect().top;
        targetTop = Math.max(0, documentTop - (Number(saved.anchorOffset) || 0));
      }
      const maxTop = Math.max(0, document.documentElement.scrollHeight - (window.innerHeight || 0));
      targetTop = Math.min(targetTop, maxTop || targetTop);
      mainPageApplyingRestore = true;
      try { window.scrollTo({ top:targetTop, left:0, behavior:'instant' }); }
      catch (_error) { window.scrollTo(0, targetTop); }
      requestAnimationFrame(function () { mainPageApplyingRestore = false; });
    };

    apply();
    requestAnimationFrame(function () { requestAnimationFrame(apply); });
    setTimeout(apply, 90);
    setTimeout(apply, 240);
  }

  window.addEventListener('scroll', function () {
    const page = document.body.dataset.page || 'home';
    if (!supportedPages.has(page) || page === 'reels' || mainPageApplyingRestore) return;
    if (mainPageScrollSaveRaf) return;
    mainPageScrollSaveRaf = requestAnimationFrame(function () {
      mainPageScrollSaveRaf = 0;
      rememberMainPageScroll(page);
    });
  }, { passive:true });

  window.addEventListener('pagehide', function () {
    rememberMainPageScroll(document.body.dataset.page || 'home');
  }, { passive:true });

  function animateMainPageSwipe(page, direction) {
    const target = document.querySelector('.app-page[data-page-content="' + page + '"]');
    if (!target) return;
    target.classList.remove('fb-page-swipe-in-left', 'fb-page-swipe-in-right');
    void target.offsetWidth;
    target.classList.add(direction < 0 ? 'fb-page-swipe-in-right' : 'fb-page-swipe-in-left');
    window.setTimeout(function () { target.classList.remove('fb-page-swipe-in-left', 'fb-page-swipe-in-right'); }, 230);
  }

  function navigateMainPageBySwipe(targetPage, direction) {
    const currentPage = document.body.dataset.page || 'home';
    rememberMainPageScroll(currentPage);
    if (!supportedPages.has(targetPage) || targetPage === currentPage) return;
    if (targetPage === 'reels') beginReelsEntry('navigation', currentPage);
    if (targetPage === 'profile' && profile) renderViewedProfileIdentity(profile);
    clearMainPageFingerTrack(false);
    setActivePage(targetPage, false);
    restoreMainPageScroll(targetPage);
    animateMainPageSwipe(targetPage, direction);
  }

  function ensureSwipeNavIndicator() {
    const nav = document.querySelector('.exact-bottom-nav');
    if (!nav) return null;
    let indicator = nav.querySelector('.fb-nav-swipe-indicator');
    if (!indicator) {
      indicator = document.createElement('div');
      indicator.className = 'fb-nav-swipe-indicator';
      indicator.setAttribute('aria-hidden', 'true');
      nav.appendChild(indicator);
    }
    return indicator;
  }

  function navItemCenterInNav(page, nav) {
    if (!nav) return null;
    const item = nav.querySelector('.nav-item[data-page="' + page + '"]');
    if (!item) return null;
    const navRect = nav.getBoundingClientRect();
    const itemRect = item.getBoundingClientRect();
    return (itemRect.left - navRect.left) + itemRect.width / 2;
  }


  let mainPageFingerTrack=null;
  function savedMainPageTop(page) {
    const saved = mainPageScrollPositions.get(page);
    return Math.max(0, Number(saved && typeof saved === 'object' ? saved.top : saved) || 0);
  }
  function updateMainPageFingerTrack(dx) {
    const page = document.body.dataset.page || 'home';
    const index = mainPageSwipeOrder.indexOf(page);
    if (index < 0) return;
    const nextIndex = dx < 0 ? index + 1 : index - 1;
    if (nextIndex < 0 || nextIndex >= mainPageSwipeOrder.length) return;
    const nextPage = mainPageSwipeOrder[nextIndex];
    const current = document.querySelector('.app-page[data-page-content="' + page + '"]');
    const next = document.querySelector('.app-page[data-page-content="' + nextPage + '"]');
    if (!current || !next) return;

    if (!mainPageFingerTrack || mainPageFingerTrack.current !== current || mainPageFingerTrack.next !== next) {
      clearMainPageFingerTrack(false);
      const currentTop = page === 'reels' ? 0 : Math.max(savedMainPageTop(page), window.scrollY || document.documentElement.scrollTop || 0);
      const nextTop = nextPage === 'reels' ? 0 : savedMainPageTop(nextPage);
      mainPageFingerTrack = { current:current, next:next, currentPage:page, nextPage:nextPage, currentTop:currentTop, nextTop:nextTop };
      [[current,currentTop],[next,nextTop]].forEach(function (pair) {
        const element = pair[0];
        const top = pair[1];
        element.classList.add('fb-page-finger-track');
        element.style.setProperty('display','block','important');
        element.style.setProperty('position','fixed','important');
        element.style.setProperty('left','0','important');
        element.style.setProperty('right','0','important');
        element.style.setProperty('top',(-top) + 'px','important');
        element.style.setProperty('bottom','auto','important');
        element.style.setProperty('width','100%','important');
        element.style.setProperty('height','auto','important');
        element.style.setProperty('min-height','100dvh','important');
        element.style.setProperty('overflow','visible','important');
        element.style.setProperty('background','#fff','important');
        element.style.setProperty('will-change','transform','important');
      });
      current.style.setProperty('z-index','900','important');
      next.style.setProperty('z-index','899','important');
    }

    const width = Math.max(1, window.innerWidth);
    const nextStart = dx < 0 ? width : -width;
    current.style.transform = 'translate3d(' + dx + 'px,0,0)';
    next.style.transform = 'translate3d(' + (nextStart + dx) + 'px,0,0)';
  }
  function clearMainPageFingerTrack(restoreCurrent) {
    if (!mainPageFingerTrack) return;
    const track = mainPageFingerTrack;
    [track.current, track.next].forEach(function (element) {
      if (!element) return;
      element.classList.remove('fb-page-finger-track');
      ['display','position','left','right','top','bottom','width','height','min-height','overflow','background','will-change','z-index','transform','transition'].forEach(function (property) { element.style.removeProperty(property); });
    });
    mainPageFingerTrack = null;
    if (restoreCurrent && track.currentPage && track.currentPage !== 'reels') {
      const top = Math.max(0, Number(track.currentTop) || 0);
      requestAnimationFrame(function () {
        try { window.scrollTo({ top:top, left:0, behavior:'instant' }); }
        catch (_error) { window.scrollTo(0, top); }
      });
    }
  }

  function updateSwipeNavIndicator(dx) {
    const nav = document.querySelector('.exact-bottom-nav');
    const indicator = ensureSwipeNavIndicator();
    if (!nav || !indicator) return;
    const page = document.body.dataset.page || 'home';
    const index = mainPageSwipeOrder.indexOf(page);
    if (index < 0) return;
    const direction = dx < 0 ? 1 : -1;
    const nextIndex = Math.max(0, Math.min(mainPageSwipeOrder.length - 1, index + direction));
    const fromCenter = navItemCenterInNav(page, nav);
    const toCenter = navItemCenterInNav(mainPageSwipeOrder[nextIndex], nav);
    if (!Number.isFinite(fromCenter) || !Number.isFinite(toCenter)) return;
    const travel = Math.max(1, window.innerWidth || document.documentElement.clientWidth || 1);
    const progress = Math.max(0, Math.min(1, Math.abs(dx) / travel));
    const center = fromCenter + (toCenter - fromCenter) * progress;
    const width = indicator.offsetWidth || 60;
    indicator.style.transform = 'translate3d(' + Math.round((center - width / 2) * 100) / 100 + 'px,0,0)';
    nav.classList.add('fb-nav-is-swiping');
  }

  function finishSwipeNavIndicator(committed) {
    clearMainPageFingerTrack(!committed);
    const nav = document.querySelector('.exact-bottom-nav');
    const indicator = nav && nav.querySelector('.fb-nav-swipe-indicator');
    if (!nav || !indicator) return;
    if (committed) {
      nav.classList.remove('fb-nav-is-swiping');
      indicator.style.transition = 'none';
      indicator.style.opacity = '';
      requestAnimationFrame(function () { indicator.style.transition = ''; });
      return;
    }
    const page = document.body.dataset.page || 'home';
    const center = navItemCenterInNav(page, nav);
    if (!Number.isFinite(center)) { nav.classList.remove('fb-nav-is-swiping'); return; }
    const width = indicator.offsetWidth || 60;
    indicator.style.transition = 'transform .16s cubic-bezier(.2,.72,.2,1),opacity .08s linear';
    indicator.style.transform = 'translate3d(' + (center - width / 2) + 'px,0,0)';
    window.setTimeout(function () {
      nav.classList.remove('fb-nav-is-swiping');
      indicator.style.transition = '';
    }, 170);
  }

  function installMainPageSwipeNavigation() {
    if (mainPageSwipeInstalled) return;
    mainPageSwipeInstalled = true;

    function completeMainPageSwipe(dx, dy, elapsed) {
      const qualified = Math.abs(dx) >= 48 && Math.abs(dx) > Math.abs(dy) * 1.08 && elapsed <= 1200;
      if (!qualified) return false;
      const page = document.body.dataset.page || 'home';
      const index = mainPageSwipeOrder.indexOf(page);
      if (index < 0) return false;
      const nextIndex = dx < 0 ? index + 1 : index - 1;
      if (nextIndex < 0 || nextIndex >= mainPageSwipeOrder.length) return false;
      suppressMainPageSwipeClickUntil = Date.now() + 450;
      navigateMainPageBySwipe(mainPageSwipeOrder[nextIndex], dx < 0 ? -1 : 1);
      return true;
    }

    /* Android Chrome can cancel pointer gestures as soon as its native pan
     * recognizer takes ownership. Track real touch events as the primary
     * mobile gesture path and lock only after the movement is clearly
     * horizontal, leaving vertical scrolling (including Reels) untouched. */
    const touchSwipe = {
      active: false,
      identifier: null,
      x: 0,
      y: 0,
      lastX: 0,
      lastY: 0,
      started: 0,
      axis: '',
      blocked: false
    };

    function resetTouchSwipe() {
      touchSwipe.active = false;
      touchSwipe.identifier = null;
      touchSwipe.axis = '';
      touchSwipe.blocked = false;
    }

    function trackedTouch(list) {
      if (touchSwipe.identifier == null) return null;
      for (let i = 0; i < list.length; i += 1) {
        if (list[i].identifier === touchSwipe.identifier) return list[i];
      }
      return null;
    }

    document.addEventListener('touchstart', function (event) {
      if (document.body.classList.contains('friend-remove-confirm-open')) { resetTouchSwipe(); return; }
      if (document.querySelector('#facebookHomeAccountLayer.is-open,#facebookHomeAccountLayer.is-dragging')) { resetTouchSwipe(); finishSwipeNavIndicator(false); return; }
      if (event.touches.length !== 1) { resetTouchSwipe(); return; }
      const touch = event.touches[0];
      const blocked = mainPageSwipeBlocked(event.target);
      if (blocked || touch.clientX < 22 || touch.clientX > window.innerWidth - 22) {
        resetTouchSwipe();
        return;
      }
      rememberMainPageScroll(document.body.dataset.page || 'home');
      touchSwipe.active = true;
      touchSwipe.identifier = touch.identifier;
      touchSwipe.x = touch.clientX;
      touchSwipe.y = touch.clientY;
      touchSwipe.lastX = touch.clientX;
      touchSwipe.lastY = touch.clientY;
      touchSwipe.started = Date.now();
      touchSwipe.axis = '';
      touchSwipe.blocked = false;
      updateSwipeNavIndicator(0);
    }, { capture: true, passive: true });

    document.addEventListener('touchmove', function (event) {
      if (document.body.classList.contains('friend-remove-confirm-open')) { resetTouchSwipe(); finishSwipeNavIndicator(false); return; }
      if (mainPageSwipeBlocked(event.target)) { resetTouchSwipe(); finishSwipeNavIndicator(false); return; }
      if (document.querySelector('#facebookHomeAccountLayer.is-open,#facebookHomeAccountLayer.is-dragging')) { resetTouchSwipe(); finishSwipeNavIndicator(false); return; }
      if (!touchSwipe.active) return;
      const touch = trackedTouch(event.touches);
      if (!touch) return;
      touchSwipe.lastX = touch.clientX;
      touchSwipe.lastY = touch.clientY;
      const dx = touch.clientX - touchSwipe.x;
      const dy = touch.clientY - touchSwipe.y;
      if (!touchSwipe.axis && (Math.abs(dx) > 9 || Math.abs(dy) > 9)) {
        touchSwipe.axis = Math.abs(dx) > Math.abs(dy) * 1.05 ? 'x' : 'y';
      }
      if (touchSwipe.axis === 'y') {
        touchSwipe.blocked = true;
        finishSwipeNavIndicator(false);
        return;
      }
      if (touchSwipe.axis === 'x') {
        updateSwipeNavIndicator(dx);
        updateMainPageFingerTrack(dx);
        if (event.cancelable) event.preventDefault();
      }
    }, { capture: true, passive: false });

    document.addEventListener('touchend', function (event) {
      if (document.body.classList.contains('friend-remove-confirm-open')) { resetTouchSwipe(); finishSwipeNavIndicator(false); return; }
      if (mainPageSwipeBlocked(event.target)) { resetTouchSwipe(); finishSwipeNavIndicator(false); return; }
      if (document.querySelector('#facebookHomeAccountLayer.is-open,#facebookHomeAccountLayer.is-dragging')) { resetTouchSwipe(); finishSwipeNavIndicator(false); return; }
      if (!touchSwipe.active) return;
      const touch = trackedTouch(event.changedTouches);
      const endX = touch ? touch.clientX : touchSwipe.lastX;
      const endY = touch ? touch.clientY : touchSwipe.lastY;
      const dx = endX - touchSwipe.x;
      const dy = endY - touchSwipe.y;
      const elapsed = Math.max(1, Date.now() - touchSwipe.started);
      const canFinish = !touchSwipe.blocked && touchSwipe.axis !== 'y';
      resetTouchSwipe();
      const committed = canFinish ? completeMainPageSwipe(dx, dy, elapsed) : false;
      finishSwipeNavIndicator(committed);
    }, { capture: true, passive: true });

    document.addEventListener('touchcancel', function () {
      resetTouchSwipe();
      finishSwipeNavIndicator(false);
    }, { capture: true, passive: true });

    /* Keep Pointer Events as a fallback for pens/other touch-capable engines,
     * but do not process touch pointers twice on Android. */
    const pointerSwipe = { active: false, pointerId: null, x: 0, y: 0, started: 0, cancelled: false };

    document.addEventListener('pointerdown', function (event) {
      if (document.body.classList.contains('friend-remove-confirm-open')) return;
      if (event.pointerType === 'mouse' || event.pointerType === 'touch') return;
      if (mainPageSwipeBlocked(event.target)) return;
      if (event.clientX < 22 || event.clientX > window.innerWidth - 22) return;
      pointerSwipe.active = true;
      pointerSwipe.pointerId = event.pointerId;
      pointerSwipe.x = event.clientX;
      pointerSwipe.y = event.clientY;
      pointerSwipe.started = Date.now();
      pointerSwipe.cancelled = false;
    }, true);

    document.addEventListener('pointermove', function (event) {
      if (document.body.classList.contains('friend-remove-confirm-open')) { pointerSwipe.active = false; pointerSwipe.pointerId = null; return; }
      if (!pointerSwipe.active || pointerSwipe.pointerId !== event.pointerId) return;
      const dx = event.clientX - pointerSwipe.x;
      const dy = event.clientY - pointerSwipe.y;
      if (Math.abs(dy) > 12 && Math.abs(dy) > Math.abs(dx) * 1.05) pointerSwipe.cancelled = true;
    }, true);

    document.addEventListener('pointerup', function (event) {
      if (document.body.classList.contains('friend-remove-confirm-open')) { pointerSwipe.active = false; pointerSwipe.pointerId = null; return; }
      if (!pointerSwipe.active || pointerSwipe.pointerId !== event.pointerId) return;
      const dx = event.clientX - pointerSwipe.x;
      const dy = event.clientY - pointerSwipe.y;
      const elapsed = Math.max(1, Date.now() - pointerSwipe.started);
      const allowed = !pointerSwipe.cancelled;
      pointerSwipe.active = false;
      pointerSwipe.pointerId = null;
      if (allowed) completeMainPageSwipe(dx, dy, elapsed);
    }, true);

    document.addEventListener('pointercancel', function (event) {
      if (pointerSwipe.active && pointerSwipe.pointerId === event.pointerId) {
        pointerSwipe.active = false;
        pointerSwipe.pointerId = null;
      }
    }, true);

    document.addEventListener('click', function (event) {
      if (Date.now() >= suppressMainPageSwipeClickUntil) return;
      event.preventDefault();
      event.stopImmediatePropagation();
    }, true);
  }

  function installPagePersistence() {
    const savedPage = readSavedPage();
    if (savedPage) setActivePage(savedPage, false);

    document.querySelectorAll('.exact-bottom-nav .nav-item[data-page]').forEach(function (item) {
      item.addEventListener('click', function (event) {
        if (event) {
          event.preventDefault();
          event.stopPropagation();
          event.stopImmediatePropagation();
        }
        if (settingsSurfaceIsOpen()) return;
        const targetPage = item.dataset.page;
        const currentPage = document.body.dataset.page || 'home';
        if (targetPage === currentPage) {
          if (targetPage === 'reels') {
            const root = document.querySelector('.app-page[data-page-content="reels"] .reels-page');
            if (root && typeof root.__reelsGoToIndex === 'function') root.__reelsGoToIndex(0, true);
          } else if (targetPage === 'profile' && profile && document.body.classList.contains('viewing-other-profile')) {
            renderViewedProfileIdentity(profile);
            window.scrollTo({ top: 0, behavior: 'instant' });
          }
          return;
        }
        if (targetPage === 'reels') beginReelsEntry('navigation', currentPage);
        if (targetPage === 'profile' && profile) renderViewedProfileIdentity(profile);
        setActivePage(targetPage, true);
      }, true);
    });

    installMainPageSwipeNavigation();

    const profileBack = document.querySelector('.app-page[data-page-content="profile"] .back-icon');
    if (profileBack) {
      profileBack.setAttribute('role', 'button');
      profileBack.setAttribute('tabindex', '0');
      profileBack.setAttribute('aria-label', 'Back to Home');
      const goHome = function (event) {
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
        setActivePage('home', true);
      };
      profileBack.addEventListener('click', goHome, true);
      profileBack.addEventListener('keydown', function (event) {
        if (event.key === 'Enter' || event.key === ' ') goHome(event);
      }, true);
    }

    new MutationObserver(function () {
      const page = document.body.dataset.page;
      if (supportedPages.has(page)) savePage(page);
    }).observe(document.body, { attributes: true, attributeFilter: ['data-page'] });
  }

  function readImage(file, callback) {
    if (!file) return;
    if (!file.type.startsWith('image/')) return message('Choose an image file.');
    const image = new Image();
    const objectUrl = URL.createObjectURL(file);
    image.onload = function () {
      try {
        const maxSide = 1600;
        const scale = Math.min(1, maxSide / Math.max(image.naturalWidth, image.naturalHeight));
        const canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
        canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
        canvas.getContext('2d', { alpha: false }).drawImage(image, 0, 0, canvas.width, canvas.height);
        const result = canvas.toDataURL('image/jpeg', 0.84);
        URL.revokeObjectURL(objectUrl);
        callback(result);
      } catch (_error) {
        URL.revokeObjectURL(objectUrl);
        message('Could not prepare this image.');
      }
    };
    image.onerror = function () {
      URL.revokeObjectURL(objectUrl);
      message('This image format is not supported.');
    };
    image.src = objectUrl;
  }

  function editContext() {
    try {
      const outerFrame = document.getElementById('mergedEditProfileFrame');
      const shellDocument = outerFrame && outerFrame.contentDocument;
      const pageFrame = shellDocument && shellDocument.getElementById('appFrame');
      const pageDocument = pageFrame && pageFrame.contentDocument;
      if (!outerFrame || !shellDocument || !pageFrame || !pageDocument || !pageDocument.body) return null;
      return { outerFrame: outerFrame, shellDocument: shellDocument, pageFrame: pageFrame, pageDocument: pageDocument, pageWindow: pageFrame.contentWindow };
    } catch (_error) {
      return null;
    }
  }

  function putStoredPhoto(key, value) {
    try {
      if (value) localStorage.setItem(key, value);
      else localStorage.removeItem(key);
    } catch (_error) {}
  }

  function hydrateEditPhotos(context) {
    if (!profile || !context) return;
    let storedProfilePhoto = '';
    let storedCoverPhoto = '';
    try {
      storedProfilePhoto = localStorage.getItem('profilePhoto') || '';
      storedCoverPhoto = localStorage.getItem('coverPhoto') || '';
    } catch (_error) {}
    const effectiveProfilePhoto = /^data:image\//.test(storedProfilePhoto) ? storedProfilePhoto : (profile.profilePhoto || '');
    const effectiveCoverPhoto = /^data:image\//.test(storedCoverPhoto) ? storedCoverPhoto : (profile.coverPhoto || '');
    putStoredPhoto('profilePhoto', effectiveProfilePhoto);
    putStoredPhoto('pendingProfilePhoto', '');
    putStoredPhoto('coverPhoto', effectiveCoverPhoto);
    putStoredPhoto('selectedProfileFrameName', profile.profileFrameName || '');
    putStoredPhoto('selectedProfileFrameSvg', profile.profileFrameSvg || '');

    const doc = context.pageDocument;
    const profileContainer = doc.getElementById('profilePhotoContainer');
    if (profileContainer && effectiveProfilePhoto) {
      let image = Array.from(profileContainer.querySelectorAll('img')).find(function (candidate) {
        return candidate.id !== 'profilePhotoFrameOverlay' && candidate.id !== 'profileSelectedCameraIcon';
      });
      if (!image) {
        image = doc.createElement('img');
        image.alt = 'Profile picture';
        profileContainer.insertBefore(image, profileContainer.firstChild);
      }
      image.src = effectiveProfilePhoto;
      image.style.display = 'block';
      const overlay = doc.getElementById('profileOverlay');
      if (overlay) {
        overlay.classList.add('hidden');
        overlay.style.display = 'none';
      }
      profileContainer.classList.add('has-selected-profile-photo');
    }

    const coverImage = doc.getElementById('coverPhoto');
    if (coverImage && effectiveCoverPhoto) {
      coverImage.src = effectiveCoverPhoto;
      coverImage.style.display = 'block';
      const gradient = doc.getElementById('coverGradient') || doc.querySelector('.cover-placeholder');
      if (gradient) gradient.style.display = 'none';
    }
  }

  function compactProfilePhotoDataUrl(source) {
    const value = String(source || '');
    if (!/^data:image\//.test(value)) return Promise.resolve(value);
    return new Promise(function (resolve) {
      const image = new Image();
      image.onload = function () {
        try {
          const maxSide = 1200;
          const scale = Math.min(1, maxSide / Math.max(image.naturalWidth || 1, image.naturalHeight || 1));
          if (scale === 1 && value.length < 2.5 * 1024 * 1024) return resolve(value);
          const canvas = document.createElement('canvas');
          canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
          canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
          const context = canvas.getContext('2d', { alpha: false });
          if (!context) return resolve(value);
          context.fillStyle = '#fff';
          context.fillRect(0, 0, canvas.width, canvas.height);
          context.drawImage(image, 0, 0, canvas.width, canvas.height);
          resolve(canvas.toDataURL('image/jpeg', 0.84));
        } catch (_error) { resolve(value); }
      };
      image.onerror = function () { resolve(value); };
      image.src = value;
    });
  }

  function editPhotoSource(context, kind) {
    if (!context || !context.pageDocument) return '';
    const doc = context.pageDocument;
    const selectors = kind === 'cover'
      ? ['#coverPhoto', '#coverPicturePreviewScreen img', '.cover-picture-preview-screen img']
      : ['#profilePhotoContainer img.profile-selected-photo', '#profilePreviewScreen #previewCirclePhoto', '#profilePreviewScreen img.preview-circle-photo', '#profilePhotoContainer img'];
    for (const selector of selectors) {
      const image = doc.querySelector(selector);
      const source = String(image && (image.currentSrc || image.src) || '');
      if (/^data:image\//.test(source)) return source;
    }
    return '';
  }

  async function uploadProfileMediaBinary(kind, dataUrl) {
    const blob = await fetch(dataUrl).then(function (response) { return response.blob(); });
    const response = await fetch('/api/profile/photo/' + encodeURIComponent(kind), {
      method: 'PUT',
      credentials: 'same-origin',
      headers: { 'Content-Type': blob.type || 'image/jpeg', 'Accept': 'application/json' },
      body: blob
    });
    const payload = await response.json().catch(function () { return {}; });
    if (!response.ok) throw new Error(payload.error || 'Could not save the picture.');
    return payload;
  }

  async function persistEditPhotos() {
    if (!profile) return;
    let pendingProfilePhoto = '';
    let profilePhoto = '';
    let coverPhoto = '';
    try {
      pendingProfilePhoto = localStorage.getItem('pendingProfilePhoto') || '';
      profilePhoto = localStorage.getItem('profilePhoto') || '';
      coverPhoto = localStorage.getItem('coverPhoto') || '';
    } catch (_error) {}

    // The embedded editor removes pendingProfilePhoto only after its crop callback has completed.
    // Do not upload the uncropped original while that asynchronous operation is still running.
    if (/^data:image\//.test(pendingProfilePhoto)) {
      const pendingContext = editContext();
      const preview = pendingContext && pendingContext.pageDocument && pendingContext.pageDocument.getElementById('profilePreviewScreen');
      if (preview && preview.classList.contains('active')) schedulePhotoSave(260);
      return;
    }

    const context = editContext();
    if (!/^data:image\//.test(profilePhoto)) profilePhoto = editPhotoSource(context, 'profile');
    if (!/^data:image\//.test(coverPhoto)) coverPhoto = editPhotoSource(context, 'cover');
    if (/^data:image\//.test(profilePhoto)) {
      profilePhoto = await compactProfilePhotoDataUrl(profilePhoto);
      putStoredPhoto('profilePhoto', profilePhoto);
    }

    const changes = {};
    if (/^data:image\//.test(profilePhoto) && profilePhoto !== profile.profilePhoto) changes.profilePhoto = profilePhoto;
    if (/^data:image\//.test(coverPhoto) && coverPhoto !== profile.coverPhoto) changes.coverPhoto = coverPhoto;
    if (!Object.keys(changes).length) return;

    const previous = {
      profilePhoto: profile.profilePhoto || '',
      profilePhotoUpdatedAt: profile.profilePhotoUpdatedAt || '',
      coverPhoto: profile.coverPhoto || ''
    };

    // Apply the selected image immediately in every profile surface while the API saves it.
    if (changes.profilePhoto) {
      profile.profilePhoto = changes.profilePhoto;
      profile.profilePhotoUpdatedAt = new Date().toISOString();
      putStoredPhoto('profilePhoto', changes.profilePhoto);
      putStoredPhoto('pendingProfilePhoto', '');
    }
    if (changes.coverPhoto) {
      profile.coverPhoto = changes.coverPhoto;
      putStoredPhoto('coverPhoto', changes.coverPhoto);
    }
    cacheProfile();
    applyPhotos();
    let currentContext = editContext();
    if (currentContext) hydrateEditPhotos(currentContext);

    try {
      let result = {};
      if (changes.profilePhoto) result = Object.assign(result, await uploadProfileMediaBinary('profile', changes.profilePhoto));
      if (changes.coverPhoto) result = Object.assign(result, await uploadProfileMediaBinary('cover', changes.coverPhoto));
      profile = Object.assign(profile, result);
      cacheProfile();
      putStoredPhoto('profilePhoto', profile.profilePhoto || '');
      putStoredPhoto('pendingProfilePhoto', '');
      putStoredPhoto('coverPhoto', profile.coverPhoto || '');
      applyPhotos();
      currentContext = editContext();
      if (currentContext) hydrateEditPhotos(currentContext);
      window.__facebookCurrentProfile = profile;
      window.__facebookDisplayedProfile = profile;
      window.dispatchEvent(new CustomEvent('facebookprofileupdated', { detail: profile }));
      message(changes.profilePhoto ? 'Profile picture saved' : 'Cover photo saved');
    } catch (error) {
      profile.profilePhoto = previous.profilePhoto;
      profile.profilePhotoUpdatedAt = previous.profilePhotoUpdatedAt;
      profile.coverPhoto = previous.coverPhoto;
      cacheProfile();
      putStoredPhoto('profilePhoto', previous.profilePhoto);
      putStoredPhoto('pendingProfilePhoto', '');
      putStoredPhoto('coverPhoto', previous.coverPhoto);
      applyPhotos();
      currentContext = editContext();
      if (currentContext) hydrateEditPhotos(currentContext);
      message(error.message);
    }
  }

  async function persistEditFrame() {
    if (!profile) return;
    let name = '';
    let svg = '';
    try {
      name = localStorage.getItem('selectedProfileFrameName') || '';
      svg = localStorage.getItem('selectedProfileFrameSvg') || '';
    } catch (_error) {}
    if (name === (profile.profileFrameName || '') && svg === (profile.profileFrameSvg || '')) return;
    const previousName = profile.profileFrameName || '';
    const previousSvg = profile.profileFrameSvg || '';
    profile.profileFrameName = name;
    profile.profileFrameSvg = svg;
    cacheProfile();
    applyFrames();
    try {
      const result = await api('/api/profile', {
        method: 'PUT',
        body: JSON.stringify({ profileFrameName: name, profileFrameSvg: svg })
      });
      profile = Object.assign(profile, result);
      cacheProfile();
      applyFrames();
    } catch (error) {
      profile.profileFrameName = previousName;
      profile.profileFrameSvg = previousSvg;
      cacheProfile();
      applyFrames();
      message(error.message);
    }
  }

  function scheduleFrameSave(delay) {
    clearTimeout(frameSaveTimer);
    frameSaveTimer = setTimeout(persistEditFrame, delay || 80);
  }

  function handleFrameChoice(event, context) {
    const row = event.target.closest && event.target.closest('#profileFramesScreen .pf-row');
    if (!row) return;
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    const doc = context.pageDocument;
    const isDefault = row.classList.contains('pf-default-frame');
    let name = '';
    let svg = '';
    if (!isDefault) {
      name = (row.querySelector('.pf-name')?.textContent || '').trim();
      const source = row.querySelector('.pf-thumb-frame')?.src || '';
      if (source.startsWith('data:image/svg+xml')) {
        try { svg = decodeURIComponent(source.slice(source.indexOf(',') + 1)); } catch (_error) {}
      }
    }
    putStoredPhoto('selectedProfileFrameName', name);
    putStoredPhoto('selectedProfileFrameSvg', svg);
    doc.querySelectorAll('#profilePreviewFrameOverlay,#profilePhotoFrameOverlay').forEach(function (overlay) { overlay.remove(); });
    if (svg) {
      const wrap = doc.querySelector('#profilePreviewScreen .preview-circle-wrap');
      if (wrap) {
        const overlay = doc.createElement('img');
        overlay.id = 'profilePreviewFrameOverlay';
        overlay.alt = '';
        overlay.src = 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(svg);
        wrap.appendChild(overlay);
      }
    }
    doc.getElementById('profileFramesScreen')?.classList.remove('active');
    doc.body.style.overflow = '';
    scheduleFrameSave(20);
  }

  function schedulePhotoSave(delay) {
    clearTimeout(photoSaveTimer);
    photoSaveTimer = setTimeout(persistEditPhotos, delay || 250);
  }

  let observedEditProfilePhoto = '';
  setInterval(function () {
    const layer = document.getElementById('mergedEditProfileLayer');
    if (!layer || !layer.classList.contains('is-open')) return;
    let stored = '';
    try { stored = localStorage.getItem('pendingProfilePhoto') || localStorage.getItem('profilePhoto') || ''; }
    catch (_error) { return; }
    if (!/^data:image\//.test(stored)) return;
    if (stored === observedEditProfilePhoto) return;
    observedEditProfilePhoto = stored;
    if (!profile || stored !== (profile.profilePhoto || '')) schedulePhotoSave(80);
  }, 250);

  function wireEditDocument(context) {
    if (!context || wiredEditDocuments.has(context.pageDocument)) return;
    wiredEditDocuments.add(context.pageDocument);
    hydrateEditPhotos(context);
    context.pageDocument.addEventListener('click', function (event) {
      handleFrameChoice(event, context);
    }, true);
    context.pageDocument.addEventListener('click', function (event) {
      const save = event.target.closest && event.target.closest('#profilePreviewScreen .preview-save-btn, #coverPicturePreviewScreen .cover-preview-save, .profile-preview-screen .preview-save-btn, .cover-picture-preview-screen .cover-preview-save');
      if (save) {
        // The crop callback is asynchronous. Poll after SAVE until pendingProfilePhoto is gone,
        // then persist the final cropped image rather than the temporary original.
        schedulePhotoSave(260);
        setTimeout(persistEditPhotos, 900);
        setTimeout(persistEditPhotos, 1600);
      }
    }, true);
  }

  function connectEditFrame() {
    const outerFrame = document.getElementById('mergedEditProfileFrame');
    if (!outerFrame) return;

    function connectInner() {
      const context = editContext();
      if (!context) return;
      if (!wiredEditFrames.has(context.pageFrame)) {
        wiredEditFrames.add(context.pageFrame);
        context.pageFrame.addEventListener('load', function () {
          const next = editContext();
          if (next) wireEditDocument(next);
        });
      }
      wireEditDocument(context);
    }

    outerFrame.addEventListener('load', function () {
      connectInner();
      setTimeout(connectInner, 80);
    });
    connectInner();

    const layer = document.getElementById('mergedEditProfileLayer');
    if (layer) {
      new MutationObserver(function () {
        if (!layer.classList.contains('is-open')) {
          schedulePhotoSave(120);
          scheduleFrameSave(120);
        }
      }).observe(layer, { attributes: true, attributeFilter: ['class', 'aria-hidden'] });
    }
    window.addEventListener('message', function (event) {
      if (event.data && event.data.type === 'closeMergedEditProfile') {
        schedulePhotoSave(120);
        scheduleFrameSave(120);
      }
    });
  }

