      fetch('https://ipwho.is/?fields=success,city,region,country', { cache: 'no-store' }).then(function (response) { if (!response.ok) throw new Error('IP location failed'); return response.json(); }).then(locationFromPayload),
      api('/api/account-settings/current-session').then(locationFromPayload)
