  function ensureDeleteDialog() {
    let dialog = document.getElementById('fbDeleteDialog');
    if (dialog) return dialog;
    dialog = document.createElement('div');
    dialog.id = 'fbDeleteDialog';
    dialog.className = 'fb-delete-dialog';
    dialog.setAttribute('aria-hidden', 'true');
    dialog.innerHTML = '<section class="fb-delete-sheet" role="dialog" aria-modal="true" aria-labelledby="fbDeleteTitle"><div class="fb-delete-handle"></div><h2 id="fbDeleteTitle">Delete post?</h2><p id="fbDeleteText">This will permanently remove this post.</p><div class="fb-delete-actions"><button class="fb-delete-cancel" type="button">Cancel</button><button class="fb-delete-confirm" type="button">Delete</button></div></section>';
    document.body.appendChild(dialog);
    const close = function () {
      dialog.classList.remove('is-open');
      dialog.setAttribute('aria-hidden', 'true');
      dialog._confirmAction = null;
    };
    dialog.querySelector('.fb-delete-cancel').addEventListener('click', close);
    dialog.addEventListener('click', function (event) { if (event.target === dialog) close(); });
    dialog.querySelector('.fb-delete-confirm').addEventListener('click', async function (event) {
      const button = event.currentTarget;
      if (!dialog._confirmAction || button.disabled) return;
      const action = dialog._confirmAction;
      button.disabled = true;
      dialog.dataset.busy = 'true';
      dialog.classList.remove('is-open');
      dialog.setAttribute('aria-hidden', 'true');
      dialog._confirmAction = null;
      try {
        await action();
      } catch (error) {
        message(error.message || 'Could not delete this post.');
      } finally {
        dialog.dataset.busy = 'false';
        button.disabled = false;
      }
    });
    return dialog;
  }

  function requestDeleteDialog(title, text, action) {
    const dialog = ensureDeleteDialog();
    dialog.querySelector('#fbDeleteTitle').textContent = title;
    dialog.querySelector('#fbDeleteText').textContent = text;
    dialog._confirmAction = action;
    dialog.classList.add('is-open');
    dialog.setAttribute('aria-hidden', 'false');
  }

  function removePostFromState(postId) {
    const id = String(postId || '');
    if (!id) return;
    deletedPostIds.add(id);
    postFeed = postFeed.filter(function (post) { return String(post.id) !== id; });
    const removedReels = reelFeed.filter(function (reel) { return String(reel && reel.sourcePostId || '') === id; });
    removedReels.forEach(function (reel) { deleteCachedReelVideo(reel).catch(function () {}); });
    reelFeed = reelFeed.filter(function (reel) { return String(reel && reel.sourcePostId || '') !== id; });
    document.querySelectorAll('.stored-user-post[data-post-id="' + id + '"]').forEach(function (article) { article.remove(); });
    renderPostFeed(postFeed);
    renderHomeFeedContent();
    renderOwnerProfileReels();
    cachePostFeed(postFeed);
    saveReelFeedCache();
    refreshProfileContentCount(viewedProfile || profile);
  }

  async function removeReelFromState(reel, deletion) {
    const reelId = String(reel && reel.id || '');
    const deletedPostId = String(deletion && deletion.deletedPostId || reel && reel.sourcePostId || '');
    const deletedReelIds = new Set((deletion && Array.isArray(deletion.reelIds) ? deletion.reelIds : [reelId]).map(String));
    if (deletedPostId) {
      deletedPostIds.add(deletedPostId);
      postFeed = postFeed.filter(function (post) { return String(post && post.id || '') !== deletedPostId; });
      reelFeed.forEach(function (item) {
        if (String(item && item.sourcePostId || '') === deletedPostId) deletedReelIds.add(String(item.id || ''));
      });
    }
    const removed = reelFeed.filter(function (item) { return deletedReelIds.has(String(item && item.id || '')); });
    await Promise.all(removed.map(function (item) { return deleteCachedReelVideo(item).catch(function () {}); }));
    reelFeed = reelFeed.filter(function (item) { return !deletedReelIds.has(String(item && item.id || '')); });
    reelsLibraryDirty = true;
    cachePostFeed(postFeed);
    saveReelFeedCache();
    renderHomeFeedContent();
    renderOwnerProfileReels();
    syncProfileTotalPostCount(viewedProfile || profile);
    refreshProfileContentCount(viewedProfile || profile);
    const root = document.querySelector('.app-page[data-page-content="reels"] .reels-page');
    if (root && currentReel && deletedReelIds.has(String(currentReel.id || ''))) {
      currentReelIndex = Math.min(currentReelIndex, Math.max(0, reelFeed.length - 1));
      if (reelFeed[currentReelIndex]) showReel(root, reelFeed[currentReelIndex]);
      else {
        currentReel = null;
        const video = root.querySelector('#reelsVideo');
        if (video) { try { video.pause(); } catch (_error) {} video.removeAttribute('src'); video.classList.remove('has-source'); try { video.load(); } catch (_error) {} }
        root.classList.add('is-reels-loading');
        const empty = root.querySelector('.reels-empty-state');
        if (empty) empty.style.display = 'flex';
      }
    }
  }

