    const edit = viewer.querySelector('[data-media-viewer-action="edit"]');
    const del = viewer.querySelector('[data-media-viewer-action="delete"]');
    edit.hidden = !ownerIsCurrent;
    edit.textContent = state.kind === 'profile-media' ? (state.mediaKind === 'cover' ? 'Edit cover photo' : 'Edit profile picture') : 'Edit post';
    del.hidden = !ownerIsCurrent || (state.kind !== 'post' && state.kind !== 'profile-media');
    del.textContent = state.kind === 'profile-media' ? 'Delete photo' : 'Delete post';
