  function renderPostMedia(container, post) {
    if (!container) return;
    const media = normalizedPostMedia(post);
    normalizedMediaStats(post);
    container.replaceChildren();
    container.hidden = !media.length;
    container.dataset.mediaCount = String(media.length);
    const visibleCount = Math.min(media.length, 4);
    for (let index = 0; index < visibleCount; index += 1) {
      const cell = document.createElement('button');
      cell.type = 'button';
      cell.className = 'fb-post-media-item';
      cell.dataset.postMediaKey = String(post.id) + ':' + String(index);
      const element = createPostMediaElement(post, index, 'fb-post-media-content');
      if (element.tagName === 'VIDEO') {
        element.controls = false;
        applyFeedVideoMutedState(element);
      }
      cell.appendChild(element);
      if (element.tagName === 'VIDEO') {
        ensureFeedVideoMuteButton(cell, element);
        registerFeedAutoplayVideo(element);
      }
      if (media.length > 4 && index === 3) {
        const remaining = document.createElement('span');
        remaining.className = 'fb-post-media-remaining';
        remaining.textContent = '+' + String(media.length - 3);
        cell.appendChild(remaining);
        cell.setAttribute('aria-label', 'View all ' + media.length + ' media items');
        cell.addEventListener('click', function () { openPostMediaGalleryPage(post); });
      } else {
        cell.setAttribute('aria-label', 'Open media ' + (index + 1) + ' of ' + media.length);
        cell.addEventListener('click', function () {
          if (media[index] && media[index].type === 'video') openPostVideoInReels(post, index);
          else openPostMediaViewer(post, index);
        });
      }
      container.appendChild(cell);
    }
  }

  function setComposerAudience(visibility) {
    const value = normalizedVisibility(visibility);
    const button = document.querySelector('[data-compose-setting="audience"]');
    if (button) {
      button.dataset.postVisibility = value;
      const label = button.querySelector('.fb-compose-audience-label') || button.querySelector('span');
      if (label) label.textContent = facebookPrivacyLabel(value);
      let icon = button.querySelector('img.fb-compose-audience-icon, img.fb-custom-compose-icon, img');
      if (!icon) {
        icon = document.createElement('img');
        button.insertBefore(icon, button.firstChild);
      }
      button.querySelectorAll('svg, img').forEach(function (candidate) {
        if (candidate !== icon) candidate.remove();
      });
      button.querySelectorAll('.fb-compose-audience-chevron').forEach(function (candidate) { candidate.remove(); });
      icon.className = 'fb-compose-audience-icon fb-custom-compose-icon';
      icon.src = facebookPrivacyAsset(value);
      icon.alt = facebookPrivacyLabel(value);
      icon.width = 18;
      icon.height = 18;
      icon.style.width = '18px';
      icon.style.height = '18px';
      icon.style.background = 'transparent';
      icon.style.objectFit = 'contain';
    }
    const sheet = document.querySelector('#fbComposerAudienceSheet');
    if (sheet) sheet.querySelectorAll('[data-composer-audience]').forEach(function (option) { option.classList.toggle('is-selected', option.dataset.composerAudience === value); });
  }

  function readComposerAudience() {
    const button = document.querySelector('[data-compose-setting="audience"]');
    return normalizedVisibility(button && button.dataset.postVisibility || 'public');
  }

