    const thumbCanvas = document.createElement('canvas');
    thumbCanvas.width = 256;
    thumbCanvas.height = 256;
    const thumbContext = thumbCanvas.getContext('2d', { alpha: false });
    thumbContext.fillStyle = '#111';
    thumbContext.fillRect(0, 0, 256, 256);
    const thumbScale = Math.min(256 / sourceWidth, 256 / sourceHeight);
    const thumbWidth = sourceWidth * thumbScale;
    const thumbHeight = sourceHeight * thumbScale;
