  function mergeLibraryReel(reel) {
    if (!reel || !reel.id) return reel;
    const existing = reelFeed.find(function (item) { return String(item.id) === String(reel.id); });
    if (existing) {
      Object.assign(existing, reel, { comments:Array.isArray(existing.comments) && existing.comments.length ? existing.comments : (reel.comments || []) });
      return existing;
    }
    reel.comments = Array.isArray(reel.comments) ? reel.comments : [];
    reelFeed.push(reel);
    saveReelFeedCache();
    return reel;
  }

