      sheet.innerHTML = '<header><button type="button" data-caption-sheet-close aria-label="Back"><svg viewBox="0 0 32 32"><path d="m20 7-9 9 9 9"/></svg></button><strong>Voice</strong><span></span></header><div class="reel-caption-voice-grid"><button type="button" data-caption-voice-choice=""><b>×</b><span>None</span></button></div>';
