        '<button type="button" data-caption-action="opacity"><img src="/reel-ui/caption-capacity-icon.png" alt=""><span>Capacity</span></button>' +
        '<button type="button" data-caption-action="style"><img src="/reel-ui/caption-style-icon.png" alt=""><span>Style</span></button>' +
        '<button type="button" data-caption-action="edit"><img src="/reel-ui/caption-edit-icon.png" alt=""><span>Edit</span></button>' +
        '<button type="button" data-caption-action="voice"><img src="/reel-ui/caption-voice-icon.png" alt=""><span>Voice</span></button>';
