          const end = Math.min(sequenceDuration(), Math.max(currentSequenceTime, voiceoverStartTime + elapsed));
          const chunks = voiceoverChunks.slice();
          const mimeType = voiceoverRecorder && voiceoverRecorder.mimeType
            ? voiceoverRecorder.mimeType
            : (chunks[0] && chunks[0].type) || 'audio/webm';
          releaseVoiceoverStream();
