        const mimeType = item.originalMimeType || item.mimeType || blob.type || 'video/mp4';
        pendingProgrammaticVideoFile = new File([blob], 'post-video-' + Date.now() + '.' + (mimeType.indexOf('webm') >= 0 ? 'webm' : 'mp4'), { type: mimeType });
