    function ensureReverseCanvas() {
      if (reverseFrameCanvas && reverseFrameCanvas.isConnected) return reverseFrameCanvas;
      const host = videoViewport || (editVideo && editVideo.parentElement);
      if (!host) return null;
      reverseFrameCanvas = document.createElement('canvas');
      reverseFrameCanvas.className = 'reel-reverse-frame-canvas';
      reverseFrameCanvas.setAttribute('aria-hidden','true');
      Object.assign(reverseFrameCanvas.style, {
        position:'absolute', inset:'0', width:'100%', height:'100%', zIndex:'5',
        objectFit:'contain', pointerEvents:'none', display:'none', background:'#000'
      });
      host.appendChild(reverseFrameCanvas);
      reverseFrameContext = reverseFrameCanvas.getContext('2d', { alpha:false, desynchronized:true });
      return reverseFrameCanvas;
    }

    function sizeReverseCanvas() {
      const canvas = ensureReverseCanvas();
      if (!canvas) return;
      const rect = (videoViewport || editVideo).getBoundingClientRect();
      const scale = Math.min(1.5, Math.max(1, window.devicePixelRatio || 1));
      const width = Math.max(2, Math.round(rect.width * scale));
      const height = Math.max(2, Math.round(rect.height * scale));
      if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; }
    }

    function drawReverseBitmap(bitmap) {
      const canvas = ensureReverseCanvas();
      if (!canvas || !reverseFrameContext || !bitmap) return;
      sizeReverseCanvas();
      const cw=canvas.width, ch=canvas.height, sw=bitmap.width||1, sh=bitmap.height||1;
      const fit=(selectedClip() && selectedClip().fit) || 'contain';
      const scale = fit === 'cover' ? Math.max(cw/sw,ch/sh) : Math.min(cw/sw,ch/sh);
      const dw=sw*scale, dh=sh*scale;
      reverseFrameContext.fillStyle='#000'; reverseFrameContext.fillRect(0,0,cw,ch);
      reverseFrameContext.drawImage(bitmap,(cw-dw)/2,(ch-dh)/2,dw,dh);
      canvas.style.filter = editVideo.style.filter || '';
    }

    function seekVideoFrame(time) {
      return new Promise(function(resolve) {
        let settled=false;
        const finish=function() {
          if(settled) return; settled=true;
          editVideo.removeEventListener('seeked',finish);
          resolve();
        };
        editVideo.addEventListener('seeked',finish,{once:true});
        try {
          if (typeof editVideo.fastSeek === 'function') editVideo.fastSeek(time);
          else editVideo.currentTime=time;
        } catch (_) { finish(); }
        setTimeout(finish,220);
      });
    }

