    let publishProgressTimer = 0;
    function setPublishProgress(value, label, stateClass) {
      const bounded = Math.max(0, Math.min(100, Number(value) || 0));
      window.clearTimeout(publishProgressTimer);
      publishProgress.classList.add('is-open');
      root.classList.add('is-reel-uploading');
      publishProgress.classList.toggle('is-success', stateClass === 'success');
      publishProgress.classList.toggle('is-error', stateClass === 'error');
      publishProgress.setAttribute('aria-hidden', 'false');
      publishProgress.querySelector('strong').textContent = label || 'Uploading reel..';
      publishProgress.querySelector('span').style.width = bounded + '%';
      publishProgress.querySelector('small').textContent = Math.round(bounded) + '%';
    }
    function hidePublishProgress(delay) {
      window.clearTimeout(publishProgressTimer);
      publishProgressTimer = window.setTimeout(function () {
        publishProgress.classList.remove('is-open', 'is-success', 'is-error');
        root.classList.remove('is-reel-uploading');
        publishProgress.setAttribute('aria-hidden', 'true');
      }, Math.max(0, Number(delay) || 0));
    }

    async function uploadReelBinary(blob, metadata, onProgress) {
      const session = await api('/api/reel-uploads', {
        method:'POST',
        body:JSON.stringify(metadata)
      });
      if(!session || !session.uploadUrl) throw new Error('Could not start the Reel upload.');
      function send(attempt) {
        return new Promise(function(resolve,reject){
          const xhr=new XMLHttpRequest();
          xhr.open('PUT',session.uploadUrl,true);
          xhr.withCredentials=true;
          xhr.timeout=4*60*1000;
          xhr.setRequestHeader('Content-Type',String(blob.type||metadata.mimeType||'application/octet-stream').split(';')[0]);
          xhr.upload.addEventListener('progress',function(event){
            if(!event.lengthComputable||typeof onProgress!=='function')return;
            const ratio=Math.max(0,Math.min(1,event.loaded/Math.max(1,event.total)));
            onProgress(8+ratio*89,ratio>=1?'Finishing Reel…':'Uploading Reel…');
          });
          xhr.upload.addEventListener('load',function(){if(typeof onProgress==='function')onProgress(98,'Finishing Reel…');});
          xhr.addEventListener('load',function(){
            let data={};try{data=JSON.parse(xhr.responseText||'{}');}catch(_error){}
            if(xhr.status>=200&&xhr.status<300)return resolve(data);
            if(attempt<1&&xhr.status>=500)return setTimeout(function(){send(attempt+1).then(resolve,reject);},500);
            reject(new Error(data.error||'Could not upload the Reel.'));
          });
          xhr.addEventListener('error',function(){
            if(attempt<1)return setTimeout(function(){send(attempt+1).then(resolve,reject);},500);
            reject(new Error('The Reel upload was interrupted. Check your connection and try again.'));
          });
          xhr.addEventListener('timeout',function(){reject(new Error('The Reel upload timed out. Try again.'));});
          xhr.send(blob);
        });
      }
      return send(0);
    }

    publish.addEventListener('click', async function () {
      const selected = file.files && file.files[0];
      if ((!selected && !selectedVideoData) || publish.disabled) return;
      publish.disabled = true;
      publish.textContent = 'Posting…';
      publishStatus.classList.remove('is-error', 'is-success');
      publishStatus.textContent = 'Preparing your edited reel…';
      try {
        const sourceVideo = selectedVideoData || (selected ? URL.createObjectURL(selected) : '');
        if (!sourceVideo) throw new Error('The selected video is no longer available. Choose it again.');
        const audience = flow.querySelector('input[name="reelAudience"]:checked')?.value || 'followers';
        const postedCaption = caption.value.trim();
        const postedAllowComments = allowComments.checked;
        const postedEditState = JSON.parse(JSON.stringify(editState));
        postedEditState.renderedDuration = Math.max(.1, sequenceDuration());
        postedEditState.previewPoster = '';
        const thumbnailBlob = await captureTemplateThumbnailBlob();
        const needsRender = reelStateNeedsRender(postedEditState);
        setPublishProgress(2, needsRender ? 'Preparing edited reel…' : 'Preparing upload…');
        closeFlow();
        let uploadBlob;
        if(!needsRender){
          if(selected&&/^video\//i.test(String(selected.type||'')))uploadBlob=selected;
          else uploadBlob=await fetch(sourceVideo).then(response=>response.blob());
          setPublishProgress(5,'Ready to upload…');
        }else{
          publish.textContent='Rendering…';publishStatus.textContent='Applying edits to the posted video…';
          uploadBlob=await renderEditedVideoData(sourceVideo,postedEditState,function(progress){setPublishProgress(progress,'Applying edits…');},true);
        }
        const detectedMimeType = String(uploadBlob && uploadBlob.type || (selected && selected.type) || 'video/webm').split(';')[0] || 'video/webm';
        postedEditState.rendered = needsRender;
        postedEditState.trimStart = 0;
        postedEditState.trimEnd = 0;
        (postedEditState.clips || []).forEach(function (clip) {
          delete clip.sourceData;
          delete clip.thumbnail;
          (clip.foregroundOverlays || []).forEach(function (item) { delete item.sourceData; });
        });
        publish.textContent = 'Posting…';
        publishStatus.textContent = 'Uploading reel…';
        setPublishProgress(8, 'Uploading Reel…');
        const posted = await uploadReelBinary(uploadBlob, {
          mimeType:detectedMimeType,
          caption:postedCaption,
          visibility:audience,
          allowComments:postedAllowComments,
          editData:postedEditState
        }, function(progress,label){ setPublishProgress(progress,label); });
        const row = posted && posted.reel;
        if (row && row.id) {
          /* Start the just-posted Reel from the local Blob already on the phone.
             There is no reason to download the same video from Render again for
             the very first playback. */
          const immediateVideoUrl = setImmediateReelPlaybackUrl(row.id, uploadBlob);
          let immediatePosterUrl='';
          if(thumbnailBlob){
            immediatePosterUrl=URL.createObjectURL(thumbnailBlob);
            fetch('/api/reels/'+encodeURIComponent(row.id)+'/thumbnail',{
              method:'PUT',credentials:'same-origin',headers:{'Content-Type':thumbnailBlob.type||'image/jpeg'},body:thumbnailBlob
            }).then(function(response){
              if(!response.ok)return;
              window.setTimeout(function(){try{URL.revokeObjectURL(immediatePosterUrl);}catch(_error){}},15000);
            }).catch(function(){});
          }
          const createdReel = {
            id: String(row.id),
            contentKey: String(row.contentKey || ('reel:' + String(row.id))),
            userId: String(row.user_id || ''),
            caption: row.caption || postedCaption,
            video: row.video || ('/api/reels/' + encodeURIComponent(row.id) + '/video?quality=high'),
            cachedVideo: immediateVideoUrl || '',
            videoHigh: row.videoHigh || ('/api/reels/' + encodeURIComponent(row.id) + '/video?quality=high'),
            videoLow: row.videoLow || ('/api/reels/' + encodeURIComponent(row.id) + '/video?quality=low'),
            thumbnailUrl: immediatePosterUrl || row.thumbnailUrl || ('/api/reels/' + encodeURIComponent(row.id) + '/thumbnail'),
            mimeType: row.mime_type || detectedMimeType,
            visibility: row.visibility || audience,
            allowComments: row.allow_comments !== false,
            editData: row.edit_data || postedEditState,
            createdAt: row.created_at || new Date().toISOString(),
            author: (profile && profile.name) || 'Facebook user',
            profilePhoto: profile && profile.id ? ('/api/users/' + encodeURIComponent(profile.id) + '/avatar') : '',
            likeCount: 0,
            likedByMe: false,
            comments: []
          };
          reelFeed = [createdReel].concat(reelFeed.filter(function (item) { return String(item.id) !== createdReel.id; }));
          renderHomeFeedContent();
          renderOwnerProfileReels();
          currentReelIndex = 0;
          saveReelFeedCache();
          root.classList.remove('is-reels-loading');
          showReel(root, createdReel);
        }
        publishStatus.classList.add('is-success');
        publishStatus.textContent = 'Reel posted successfully.';
        setPublishProgress(100, 'Reel posted', 'success');
        hidePublishProgress(1200);
        reelMessage(root, 'Reel posted');
        window.setTimeout(function refreshPostedFeed() {
          if (loadLatestReel.pending) {
            window.setTimeout(refreshPostedFeed, 500);
            return;
          }
          loadLatestReel();
        }, 900);
      } catch (error) {
        publishStatus.classList.add('is-error');
        publishStatus.textContent = error && error.message ? error.message : 'Could not publish the reel.';
        setPublishProgress(100, error && error.message ? error.message : 'Could not publish the reel.', 'error');
        hidePublishProgress(4500);
        reelMessage(root, error.message);
      } finally {
        publish.textContent = 'Post reel';
        publish.disabled = false;
      }
    });
