        if (!textDrag || textDrag.id !== event.pointerId) return;
        const dx = event.clientX - textDrag.x;
        const dy = event.clientY - textDrag.y;
        if (!textDrag.moved && Math.hypot(dx, dy) < 5) return;
        textDrag.moved = true;
        event.preventDefault();
        const bounds = previewStage.getBoundingClientRect();
        if (!bounds.width || !bounds.height) return;
        target.textPositionX = Math.min(.9, Math.max(.1, (event.clientX - bounds.left) / bounds.width));
