      'fashion-beat': { ins:['folding-fan','flip-in'], outs:['folding-fan','flip-out'], combos:['rotate','pulse'], magics:['velocity-zoom','velocity-flash'], transitions:['spin','zoom'], preview:'fashion' },
      'food-pop': { ins:['bounce-in','zoom-in'], outs:['bounce-out','zoom-out'], combos:['pulse','bounce'], magics:['speed-zoom','camera-motion'], transitions:['zoom','dissolve'], preview:'pop' },
      'soft-memories': { ins:['fade-in'], outs:['fade-out'], combos:['swing','pan-zoom'], magics:['slowmo-zoom','camera-motion'], transitions:['dissolve','blur'], preview:'memory' },
