  function updateManagePostsSummary(){const page=ensureManagePostsPage();const type=page.dataset.manageType||'all';const names={all:'All content',reels:'Reels',text:'Text',stickers:'Stickers',stories:'Stories',music:'Music',photos:'Photos',location:'Location'};const bits=[names[type]||'All content'];if(page.dataset.manageFrom||page.dataset.manageTo)bits.push((page.dataset.manageFrom||'Any time')+' – '+(page.dataset.manageTo||'Today'));page.querySelector('[data-manage-summary]').textContent=bits.join(' · ');page.querySelector('[data-manage-filter]').classList.toggle('is-active',type!=='all');page.querySelector('[data-manage-date]').classList.toggle('is-active',Boolean(page.dataset.manageFrom||page.dataset.manageTo));}
