  async function loadManagePosts(reset,append){const page=ensureManagePostsPage();if(managePostsLoading)return;if(reset){managePostsItems=[];managePostsNextCursor='';page.querySelector('[data-manage-list]').innerHTML=managePostsLoadingMarkup();}managePostsLoading=true;try{const params=new URLSearchParams({type:page.dataset.manageType||'all',limit:'18'});if(page.dataset.manageFrom)params.set('from',page.dataset.manageFrom);if(page.dataset.manageTo)params.set('to',page.dataset.manageTo);if(append&&managePostsNextCursor)params.set('cursor',managePostsNextCursor);const data=await api('/api/manage-posts?'+params.toString());const incoming=Array.isArray(data.items)?data.items:[];managePostsItems=append?managePostsItems.concat(incoming):incoming;managePostsNextCursor=data.nextCursor||'';renderManagePosts();}catch(error){page.querySelector('[data-manage-list]').innerHTML='<div class="fb-manage-empty">'+escapeHtml(error.message||'Could not load your content.')+'</div>';}finally{managePostsLoading=false;}}
